-- LOCAL PRO ONLY. Private CRM gateway preserves exact legacy payloads/receipts.
-- Atomic manual opportunity + optional channel; no directory-card fabrication,
-- appointment, account, quote, work, acceptance, debt, notification or delivery.
begin;
create table if not exists pro_lead_origin_creates(owner_id uuid not null references profiles(id)on delete cascade,action_id uuid not null,lead_kind text not null default'manual'check(lead_kind='manual'),lead_id uuid not null,core_action_id uuid not null,input jsonb not null,result jsonb not null,at timestamptz not null default now(),primary key(owner_id,action_id),unique(owner_id,lead_id),unique(owner_id,core_action_id),foreign key(owner_id,lead_kind,lead_id)references pro_lead_center_records(owner_id,kind,id)on delete cascade);
create or replace function public.pro_lead_private_core_action_read(p_actor uuid,p_action uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare r pro_lead_center_actions;begin perform pro_lead_origin_owner(p_actor);select * into r from pro_lead_center_actions where owner_id=p_actor and action_id=p_action;if not found then return jsonb_build_object('receipt',null);end if;perform pro_lead_origin_item(p_actor,r.input->>'kind',(r.input->>'id')::uuid);return jsonb_build_object('receipt',jsonb_build_object('input',r.input,'result',r.result));end $$;
create or replace function public.pro_lead_private_core_materialize(p_actor uuid)returns void language plpgsql security invoker set search_path=public,pg_temp as $$begin perform pro_lead_origin_owner(p_actor);perform pro_lead_center_catalog_materialize(p_actor);end $$;
create or replace function public.pro_lead_private_core_mutate(p_actor uuid,p_input jsonb) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$declare aid uuid;lid uuid;act text;k text;expected text[];rev integer;catalog_revision integer;r pro_lead_center_records;prior pro_lead_center_actions;c pro_clients;before_json jsonb;after_json jsonb;answer jsonb;forecast jsonb;day date;sid text;mode_value text;before_name text;after_name text;begin
 perform pro_lead_origin_owner(p_actor);
 if jsonb_typeof(p_input) is distinct from 'object' or jsonb_typeof(p_input->'action') is distinct from 'string' or jsonb_typeof(p_input->'kind') is distinct from 'string' or jsonb_typeof(p_input->'actionId') is distinct from 'string' or jsonb_typeof(p_input->'id') is distinct from 'string' or jsonb_typeof(p_input->'revision') is distinct from 'number' or not coalesce(p_input->>'revision'~'^[0-9]{1,10}$',false) or(p_input->>'revision')::numeric not between 0 and 2147483646 then raise exception 'Invalid opportunity operation' using errcode='22023';end if;
 act:=p_input->>'action';k:=p_input->>'kind';aid:=(p_input->>'actionId')::uuid;lid:=(p_input->>'id')::uuid;rev:=(p_input->>'revision')::integer;
 expected:=case act when 'create' then array['action','actionId','address','catalogRevision','clientId','description','forecast','id','kind','revision','sourceLabel','stageId','stageMode','title'] when 'update' then array['action','actionId','address','clientId','description','forecast','id','kind','revision','sourceLabel','title'] when 'set_stage' then array['action','actionId','catalogRevision','id','kind','revision','stageId'] when 'return_auto' then array['action','actionId','catalogRevision','id','kind','revision'] when 'archive' then array['action','actionId','id','kind','revision'] when 'restore' then array['action','actionId','id','kind','revision'] else null end;
 if aid is null or lid is null or expected is null or(select array_agg(key order by key) from jsonb_object_keys(p_input)key) is distinct from expected or k not in('manual','request') or k='request' and act not in('archive','restore') then raise exception 'Invalid source or fields' using errcode='22023';end if;
 -- Matches the existing contact writer: owner advisory precedes contact rows.
