  sid:=case when act='set_stage' then p_input->>'stageId' else null end;if act='set_stage' then perform pro_lead_private_core_materialize(p_actor);if sid is null or not exists(select 1 from pro_request_pipeline_stages where owner_id=p_actor and id=sid and not hidden and not retired) then raise exception 'Choose a visible stage' using errcode='40001';end if;end if;
  update pro_lead_center_records set stage_mode=case when act='set_stage' then 'manual' else 'automatic' end,stage_id=sid,revision=revision+1,updated_at=now() where owner_id=p_actor and kind='manual' and id=lid;
 else
  if coalesce(r.archived,false)=(act='archive') then raise exception 'Opportunity archive state changed' using errcode='40001';end if;
  if k='request' and r.id is null then insert into pro_lead_center_records(owner_id,kind,id,request_id,revision,archived) values(p_actor,'request',lid,lid,1,true);
