 perform pg_advisory_xact_lock(hashtextextended(p_actor::text,0));perform pg_advisory_xact_lock(hashtextextended('pro-lead-origin-create:'||p_actor::text||':'||aid::text,0));perform pg_advisory_xact_lock(hashtextextended('pro-lead-center-action:'||p_actor::text||':'||core_aid::text,0));perform pg_advisory_xact_lock(hashtextextended('pro-lead-origin-action:'||p_actor::text||':'||aid::text,0));perform pg_advisory_xact_lock(hashtextextended('pro-request-pipeline-catalog:'||p_actor::text,0));perform pg_advisory_xact_lock(hashtextextended('pro-lead-origin-catalog:'||p_actor::text,0));perform pro_lead_origin_owner(p_actor);
 select*into prior from pro_lead_origin_creates where owner_id=p_actor and action_id=aid;if found then perform pro_lead_origin_create_current(p_actor,prior.lead_id);if prior.input is distinct from p_input then raise exception'Creation action reused'using errcode='22023';end if;return prior.result;end if;
 -- There is no partial-success adoption: the complete transaction owns every child.
 if exists(select 1 from pro_lead_center_actions where owner_id=p_actor and action_id=aid)or exists(select 1 from pro_lead_center_catalog_actions where owner_id=p_actor and action_id=aid)or exists(select 1 from pro_request_pipeline_actions where owner_id=p_actor and action_id=aid)or exists(select 1 from pro_lead_center_records where owner_id=p_actor and kind='manual'and id=lid)or exists(select 1 from pro_lead_center_actions where owner_id=p_actor and action_id=core_aid)or exists(select 1 from pro_lead_center_catalog_actions where owner_id=p_actor and action_id=core_aid)or exists(select 1 from pro_request_pipeline_actions where owner_id=p_actor and action_id=core_aid)or exists(select 1 from pro_lead_origin_actions where owner_id=p_actor and action_id=aid)or exists(select 1 from pro_lead_origin_assignments where owner_id=p_actor and kind='manual'and id=lid)then raise exception'Existing lead or child action has no combined origin'using errcode='40001';end if;
 if cid is not null then origin_result:=pro_lead_origin_channel_json(p_actor,cid);if origin_result is null or(origin_result->>'archived')::boolean or(origin_result->>'revision')::integer<>channel_rev then raise exception'Choose a current active channel'using errcode='40001';end if;end if;
 lead_result:=pro_lead_private_core_mutate(p_actor,lead_input);origin_result:=null;
 if cid is not null then origin_result:=pro_lead_origin_mutate(p_actor,jsonb_build_object('action','assign','actionId',aid,'kind','manual','id',lid,'revision',0,'channelId',cid,'channelRevision',channel_rev));end if;
