 answer:=jsonb_build_object('action','create_lead','lead',lead_result,'origin',origin_result);insert into pro_lead_origin_creates(owner_id,action_id,lead_id,core_action_id,input,result)values(p_actor,aid,lid,core_aid,p_input,answer);return answer;end $$;
-- A committed parent UUID cannot be stolen by a legacy writer that does not
-- know the new ledger. Its fresh state/history writes roll back with this error.
create or replace function public.pro_lead_origin_create_child_guard()returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$begin if exists(select 1 from pro_lead_origin_creates where owner_id=new.owner_id and action_id=new.action_id)then raise exception'Combined parent action identity is reserved'using errcode='40001';end if;return new;end $$;
drop trigger if exists pro_lead_origin_create_core_action_guard on pro_lead_center_actions;
create trigger pro_lead_origin_create_core_action_guard before insert on pro_lead_center_actions for each row execute function pro_lead_origin_create_child_guard();
drop trigger if exists pro_lead_origin_create_origin_action_guard on pro_lead_origin_actions;
create trigger pro_lead_origin_create_origin_action_guard before insert on pro_lead_origin_actions for each row execute function pro_lead_origin_create_child_guard();
create or replace function public.pro_lead_origin_create_immutable()returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$begin raise exception'Immutable combined creation receipt'using errcode='23514';end $$;
drop trigger if exists pro_lead_origin_create_immutable on pro_lead_origin_creates;
create trigger pro_lead_origin_create_immutable before update on pro_lead_origin_creates for each row execute function pro_lead_origin_create_immutable();
alter table pro_lead_origin_creates enable row level security;
revoke all on pro_lead_origin_creates from public,anon,authenticated;grant all on pro_lead_origin_creates to service_role;
do $$declare f record;begin for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and(p.proname like'pro_lead_private_core_%'or p.proname in('pro_lead_origin_create','pro_lead_origin_create_current','pro_lead_origin_create_action_read','pro_lead_origin_create_immutable','pro_lead_origin_create_child_guard'))loop execute format('revoke all on function %s from public,anon,authenticated',f.signature);execute format('grant execute on function %s to service_role',f.signature);end loop;end $$;
commit;
notify pgrst,'reload schema';

-- ===== lead-private-stages-local.sql =====
-- LOCAL PRO ONLY. Private commercial-stage catalogue gateway.
-- Exact legacy mutation/result/receipt tables and payloads; no public-directory
-- prerequisite, no public booking changes, no team access or real sends.
begin;
create or replace function public.pro_lead_private_stage_catalog(p_actor uuid)returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$select pro_lead_origin_stage_catalog(p_actor)$$;
create or replace function public.pro_lead_private_stage_pipeline_action_read(p_actor uuid,p_action uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare r pro_request_pipeline_actions;begin perform pro_lead_origin_owner(p_actor);select * into r from pro_request_pipeline_actions where owner_id=p_actor and action_id=p_action;if not found or not coalesce(r.input->>'action'in('stage_save','stage_reorder','stage_visibility','stage_retire'),false)then return jsonb_build_object('receipt',null);end if;if r.input?'requestId' and not exists(select 1 from pro_appointment_requests where owner_id=p_actor and id=(r.input->>'requestId')::uuid) then raise exception 'Request unavailable' using errcode='42501';end if;return jsonb_build_object('receipt',jsonb_build_object('input',r.input,'result',r.result));end $$;
create or replace function public.pro_lead_private_stage_pipeline_mutate(p_actor uuid,p_input jsonb) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$declare act text;aid uuid;sid text;rid uuid;expected text[];catalog_revision integer;current_revision integer;state_revision integer;catalog jsonb;old_catalog jsonb;before_json jsonb;after_json jsonb;answer jsonb;lead jsonb;auto jsonb;target text;stage_row pro_request_pipeline_stages;ref pro_request_pipeline_states;receipt pro_request_pipeline_actions;position_value integer;reassigned integer:=0;before_name text;after_name text;builtin_order text[];ids text[];begin
 perform pro_lead_origin_owner(p_actor);
 if jsonb_typeof(p_input) is distinct from 'object' or jsonb_typeof(p_input->'action') is distinct from 'string' or jsonb_typeof(p_input->'actionId') is distinct from 'string' or jsonb_typeof(p_input->'catalogRevision') is distinct from 'number' or not coalesce(p_input->>'catalogRevision'~'^[0-9]{1,10}$',false) or(p_input->>'catalogRevision')::numeric not between 0 and 2147483646 then raise exception 'Invalid pipeline operation' using errcode='22023';end if;
 act:=p_input->>'action';if act not in('stage_save','stage_reorder','stage_visibility','stage_retire')then raise exception'Only catalogue actions belong to this gateway'using errcode='22023';end if;aid:=(p_input->>'actionId')::uuid;catalog_revision:=(p_input->>'catalogRevision')::integer;
 expected:=case act when 'stage_save' then array['action','actionId','catalogRevision','name','stageId'] when 'stage_reorder' then array['action','actionId','catalogRevision','stageIds'] when 'stage_visibility' then array['action','actionId','catalogRevision','hidden','reassignToId','stageId'] when 'stage_retire' then array['action','actionId','catalogRevision','reassignToId','stageId'] when 'set_stage' then array['action','actionId','catalogRevision','requestId','revision','stageId'] when 'return_auto' then array['action','actionId','catalogRevision','requestId','revision'] else null end;
 if expected is null or(select array_agg(key order by key) from jsonb_object_keys(p_input)key) is distinct from expected or aid is null then raise exception 'Unexpected pipeline fields' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_actor::text,0));perform pg_advisory_xact_lock(hashtextextended('pro-request-pipeline-action:'||p_actor::text||':'||aid::text,0));perform pg_advisory_xact_lock(hashtextextended('pro-request-pipeline-catalog:'||p_actor::text,0));perform pro_lead_origin_owner(p_actor);
 select * into receipt from pro_request_pipeline_actions where owner_id=p_actor and action_id=aid;if found then if receipt.input is distinct from p_input then raise exception 'Pipeline action reused' using errcode='22023';end if;perform pro_lead_private_stage_pipeline_action_read(p_actor,aid);return receipt.result;end if;
 old_catalog:=pro_lead_private_stage_catalog(p_actor);current_revision:=(old_catalog->>'revision')::integer;if current_revision<>catalog_revision then raise exception 'Lead stages changed' using errcode='40001';end if;
 -- Materialize defaults only on an explicit mutation. Reads never backfill.
 insert into pro_request_pipeline_heads values(p_actor,0) on conflict do nothing;
 insert into pro_request_pipeline_stages(owner_id,id,position) select p_actor,v,(n-1)::integer from unnest(array['new','followed_up','connected','meeting_scheduled','estimate_sent','won']) with ordinality x(v,n) on conflict do nothing;
 if act in('set_stage','return_auto') then
  if jsonb_typeof(p_input->'requestId') is distinct from 'string' or jsonb_typeof(p_input->'revision') is distinct from 'number' or not coalesce(p_input->>'revision'~'^[0-9]{1,10}$',false) or(p_input->>'revision')::numeric not between 0 and 2147483646 then raise exception 'Invalid request state' using errcode='22023';end if;
  rid:=(p_input->>'requestId')::uuid;if not exists(select 1 from pro_appointment_requests where owner_id=p_actor and id=rid) then raise exception 'Request unavailable' using errcode='42501';end if;
  before_json:=pro_request_pipeline_state(p_actor,rid);state_revision:=(before_json->>'revision')::integer;if state_revision<>(p_input->>'revision')::integer then raise exception 'Commercial stage changed' using errcode='40001';end if;
  if act='set_stage' then sid:=p_input->>'stageId';select * into stage_row from pro_request_pipeline_stages where owner_id=p_actor and id=sid and not hidden and not retired;if not found then raise exception 'Choose an active stage' using errcode='40001';end if;
  else sid:=null;end if;
  select name into before_name from pro_request_pipeline_stages where owner_id=p_actor and id=before_json->>'stageId';
  insert into pro_request_pipeline_states(owner_id,request_id,mode,stage_id,revision) values(p_actor,rid,case when act='set_stage' then 'manual' else 'automatic' end,sid,state_revision+1) on conflict(owner_id,request_id) do update set mode=excluded.mode,stage_id=excluded.stage_id,revision=excluded.revision,updated_at=now();
  after_json:=pro_request_pipeline_state(p_actor,rid);lead:=pro_lead_origin_request(p_actor,rid);catalog:=pro_lead_private_stage_catalog(p_actor);select value into auto from jsonb_array_elements(catalog->'stages') where value->>'id'=lead->>'effectiveStageId';select name into after_name from pro_request_pipeline_stages where owner_id=p_actor and id=sid;
  insert into pro_request_pipeline_history values(p_actor,rid,aid,act,before_json,after_json,before_name,after_name,now());answer:=jsonb_build_object('action',act,'catalogRevision',current_revision,'state',after_json,'before',before_json,'stage',auto,'evidence',lead->'evidence');
 else
  if current_revision>=2147483647 then raise exception 'Stage catalogue revision exhausted' using errcode='40001';end if;
  if act='stage_save' then
   if jsonb_typeof(p_input->'stageId') is distinct from 'string' or jsonb_typeof(p_input->'name') is distinct from 'string' or length(btrim(p_input->>'name')) not between 1 and 25 or p_input->>'name'~'[[:cntrl:]]' then raise exception 'Invalid custom stage' using errcode='22023';end if;
   sid:=((p_input->>'stageId')::uuid)::text;select * into stage_row from pro_request_pipeline_stages where owner_id=p_actor and id=sid;
   if found then if stage_row.retired then raise exception 'Retired stage identity cannot be reused' using errcode='40001';end if;update pro_request_pipeline_stages set name=btrim(p_input->>'name') where owner_id=p_actor and id=sid;
   else if(select count(*) from pro_request_pipeline_stages where owner_id=p_actor and not retired and name is not null)>=12 then raise exception 'Twelve custom stages maximum' using errcode='40001';end if;select count(*) into position_value from pro_request_pipeline_stages where owner_id=p_actor and not retired;insert into pro_request_pipeline_stages(owner_id,id,name,position) values(p_actor,sid,btrim(p_input->>'name'),position_value);end if;
  elsif act='stage_reorder' then
   if jsonb_typeof(p_input->'stageIds') is distinct from 'array' or jsonb_array_length(p_input->'stageIds') not between 6 and 18 or exists(select 1 from jsonb_array_elements(p_input->'stageIds')x where jsonb_typeof(x)<>'string') then raise exception 'Invalid stage order' using errcode='22023';end if;
   select array_agg(value order by ord) into ids from jsonb_array_elements_text(p_input->'stageIds')with ordinality x(value,ord);select array_agg(value order by ord) into builtin_order from jsonb_array_elements_text(p_input->'stageIds')with ordinality x(value,ord) where value in('new','followed_up','connected','meeting_scheduled','estimate_sent','won');
   if builtin_order is distinct from array['new','followed_up','connected','meeting_scheduled','estimate_sent','won'] or cardinality(ids)<>(select count(distinct x) from unnest(ids)x) or cardinality(ids)<>(select count(*) from pro_request_pipeline_stages where owner_id=p_actor and not retired) or exists(select 1 from unnest(ids)x where not exists(select 1 from pro_request_pipeline_stages where owner_id=p_actor and id=x and not retired)) then raise exception 'Stage order changed' using errcode='40001';end if;
   update pro_request_pipeline_stages s set position=x.ord-1 from unnest(ids)with ordinality x(id,ord) where s.owner_id=p_actor and s.id=x.id;
  else
   if jsonb_typeof(p_input->'stageId') is distinct from 'string' or jsonb_typeof(p_input->'reassignToId') not in('string','null') then raise exception 'Invalid stage visibility' using errcode='22023';end if;
   sid:=p_input->>'stageId';target:=p_input->>'reassignToId';select * into stage_row from pro_request_pipeline_stages where owner_id=p_actor and id=sid and not retired;if not found then raise exception 'Stage unavailable' using errcode='40001';end if;
   if act='stage_retire' then if stage_row.name is null then raise exception 'Built-in stages cannot be retired' using errcode='22023';end if;
   elsif jsonb_typeof(p_input->'hidden') is distinct from 'boolean' or(p_input->>'hidden')::boolean=stage_row.hidden or sid in('new','won') and(p_input->>'hidden')::boolean then raise exception 'Invalid stage visibility transition' using errcode='22023';end if;
   if act='stage_retire' or(p_input->>'hidden')::boolean then
    if target is null or target=sid or not exists(select 1 from pro_request_pipeline_stages where owner_id=p_actor and id=target and not hidden and not retired) then raise exception 'Choose a visible replacement stage' using errcode='40001';end if;
    select name into after_name from pro_request_pipeline_stages where owner_id=p_actor and id=target;
    for ref in select * from pro_request_pipeline_states where owner_id=p_actor and mode='manual' and stage_id=sid order by request_id for update loop
     if ref.revision>=2147483647 then raise exception 'Request stage revision exhausted' using errcode='40001';end if;before_json:=pro_request_pipeline_state(p_actor,ref.request_id);update pro_request_pipeline_states set stage_id=target,revision=revision+1,updated_at=now() where owner_id=p_actor and request_id=ref.request_id;after_json:=pro_request_pipeline_state(p_actor,ref.request_id);insert into pro_request_pipeline_history values(p_actor,ref.request_id,aid,'reassign_stage',before_json,after_json,stage_row.name,after_name,now());reassigned:=reassigned+1;
    end loop;
    update pro_request_pipeline_stages set reassign_to_id=target where owner_id=p_actor and hidden and reassign_to_id=sid;
    update pro_request_pipeline_stages set hidden=true,reassign_to_id=target,retired=(act='stage_retire') where owner_id=p_actor and id=sid;
    if act='stage_retire' then with ordered as(select id,row_number()over(order by position)-1 pos from pro_request_pipeline_stages where owner_id=p_actor and not retired)update pro_request_pipeline_stages s set position=o.pos from ordered o where s.owner_id=p_actor and s.id=o.id;end if;
   else if target is not null then raise exception 'Showing a stage needs no reassignment' using errcode='22023';end if;update pro_request_pipeline_stages set hidden=false,reassign_to_id=null where owner_id=p_actor and id=sid;end if;
  end if;
  update pro_request_pipeline_heads set revision=current_revision+1 where owner_id=p_actor;catalog:=pro_lead_private_stage_catalog(p_actor);answer:=jsonb_build_object('action',act,'catalog',catalog,'reassigned',reassigned);
 end if;
 perform pro_lead_origin_owner(p_actor);insert into pro_request_pipeline_actions(owner_id,action_id,input,result,actor_name) values(p_actor,aid,p_input,answer,pro_team_name(p_actor));perform pro_lead_origin_owner(p_actor);return answer;end $$;
create or replace function public.pro_lead_private_stage_read_action(p_actor uuid,p_action uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare r pro_lead_center_catalog_actions;begin perform pro_lead_origin_owner(p_actor);select * into r from pro_lead_center_catalog_actions where owner_id=p_actor and action_id=p_action;if found then if not coalesce(r.input->>'action'in('stage_save','stage_reorder','stage_visibility','stage_retire'),false)then return jsonb_build_object('receipt',null);end if;return jsonb_build_object('receipt',jsonb_build_object('input',r.input,'result',r.result));end if;return pro_lead_private_stage_pipeline_action_read(p_actor,p_action);end $$;
create or replace function public.pro_lead_private_stage_mutate(p_actor uuid,p_input jsonb) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$declare aid uuid;act text;sid text;target text;r pro_lead_center_catalog_actions;old_receipt pro_request_pipeline_actions;ref pro_lead_center_records;answer jsonb;before_json jsonb;after_json jsonb;before_name text;after_name text;moved integer:=0;begin
 perform pro_lead_origin_owner(p_actor);if jsonb_typeof(p_input)is distinct from'object'or jsonb_typeof(p_input->'action')is distinct from'string'or jsonb_typeof(p_input->'actionId')is distinct from'string'then raise exception'Invalid catalogue action'using errcode='22023';end if;aid:=(p_input->>'actionId')::uuid;act:=p_input->>'action';if aid is null or act is null or act not in('stage_save','stage_reorder','stage_visibility','stage_retire') then raise exception 'Invalid catalogue action' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_actor::text,0));perform pg_advisory_xact_lock(hashtextextended('pro-request-pipeline-action:'||p_actor::text||':'||aid::text,0));perform pg_advisory_xact_lock(hashtextextended('pro-request-pipeline-catalog:'||p_actor::text,0));perform pro_lead_origin_owner(p_actor);
 select * into r from pro_lead_center_catalog_actions where owner_id=p_actor and action_id=aid;if found then if r.input is distinct from p_input then raise exception 'Catalogue action reused' using errcode='22023';end if;return r.result;end if;
 if exists(select 1 from pro_lead_center_actions where owner_id=p_actor and action_id=aid)or exists(select 1 from pro_lead_origin_creates where owner_id=p_actor and action_id=aid)or exists(select 1 from pro_lead_origin_actions where owner_id=p_actor and action_id=aid)then raise exception 'Action identity already used' using errcode='40001';end if;
 select * into old_receipt from pro_request_pipeline_actions where owner_id=p_actor and action_id=aid;if found then
  if old_receipt.input is distinct from p_input then raise exception 'Catalogue action reused' using errcode='22023';end if;
  if exists(select 1 from pro_lead_center_records where owner_id=p_actor and kind='manual' and created_at<=old_receipt.at) then raise exception 'Legacy catalogue result cannot establish mixed provenance' using errcode='40001';end if;
  insert into pro_lead_center_catalog_actions values(p_actor,aid,p_input,old_receipt.result,pro_team_name(p_actor),true,now());perform pro_lead_origin_owner(p_actor);return old_receipt.result;
 end if;
 sid:=p_input->>'stageId';target:=p_input->>'reassignToId';select name into before_name from pro_request_pipeline_stages where owner_id=p_actor and id=sid;select name into after_name from pro_request_pipeline_stages where owner_id=p_actor and id=target;
 perform set_config('pro.lead_center_catalog',p_actor::text||':'||aid::text,true);answer:=pro_lead_private_stage_pipeline_mutate(p_actor,p_input);
 if act='stage_retire' or act='stage_visibility' and(p_input->>'hidden')::boolean then
  for ref in select * from pro_lead_center_records where owner_id=p_actor and kind='manual' and stage_mode='manual' and stage_id=sid order by id for update loop
   if ref.revision>=2147483647 then raise exception 'Opportunity revision exhausted' using errcode='40001';end if;before_json:=pro_lead_origin_item(p_actor,'manual',ref.id);update pro_lead_center_records set stage_id=target,revision=revision+1,updated_at=now() where owner_id=p_actor and kind='manual' and id=ref.id;after_json:=pro_lead_origin_item(p_actor,'manual',ref.id);insert into pro_lead_center_history values(p_actor,'manual',ref.id,aid,'reassign_stage',before_json,after_json,before_name,after_name,now());moved:=moved+1;
  end loop;
 end if;
 perform set_config('pro.lead_center_catalog','',true);answer:=jsonb_set(answer,'{reassigned}',to_jsonb((answer->>'reassigned')::integer+moved));insert into pro_lead_center_catalog_actions values(p_actor,aid,p_input,answer,pro_team_name(p_actor),false,now());perform pro_lead_origin_owner(p_actor);return answer;end $$;
-- No table, column, index, trigger or old function definition is changed.
do $$declare f record;begin for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname like'pro_lead_private_stage_%'loop execute format('revoke all on function %s from public,anon,authenticated',f.signature);execute format('grant execute on function %s to service_role',f.signature);end loop;end $$;
commit;
notify pgrst,'reload schema';

-- ===== lead-commercial-progress-local.sql =====
-- LOCAL PRO ONLY. Read-only commercial progress from explicit conversion facts.
-- No stage/core/receipt backfill. Existing payloads and history remain unchanged.
begin;
create or replace function public.pro_lead_commercial_work_authorize(p_actor uuid,p_action uuid) returns void language plpgsql security invoker set search_path=public,pg_temp as $$declare r pro_manual_lead_works;begin
 perform pro_lead_origin_owner(p_actor);select * into r from pro_manual_lead_works where owner_id=p_actor and action_id=p_action;if not found then raise exception 'Conversion unavailable' using errcode='42501';end if;
 if not exists(select 1 from pro_lead_center_records where owner_id=p_actor and kind='manual' and id=r.lead_id)or not exists(select 1 from pro_work where user_id=p_actor and id=r.work_id_text and "clientId"=r.source_client_id and "bookingClientId"is null)then raise exception 'Conversion ownership unavailable' using errcode='42501';end if;end $$;
create or replace function public.pro_lead_commercial_work_action_read(p_actor uuid,p_action uuid) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$declare r pro_manual_lead_works;begin
 perform pro_lead_origin_owner(p_actor);select * into r from pro_manual_lead_works where owner_id=p_actor and action_id=p_action;if not found then return jsonb_build_object('receipt',null);end if;perform pro_lead_commercial_work_authorize(p_actor,p_action);return jsonb_build_object('receipt',jsonb_build_object('input',r.input,'result',r.result));end $$;
create or replace function public.pro_lead_commercial_work_mapping_read(p_actor uuid,p_lead uuid) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$declare r pro_manual_lead_works;begin
 perform pro_lead_origin_owner(p_actor);if not exists(select 1 from pro_lead_center_records where owner_id=p_actor and kind='manual' and id=p_lead)then raise exception 'Opportunity unavailable' using errcode='P0002';end if;
 select * into r from pro_manual_lead_works where owner_id=p_actor and lead_id=p_lead;if not found then return jsonb_build_object('mapping',null);end if;perform pro_lead_commercial_work_authorize(p_actor,r.action_id);return jsonb_build_object('mapping',r.result);end $$;
create or replace function public.pro_lead_commercial_work_context(p_actor uuid,p_lead uuid) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$declare l pro_lead_center_records;c pro_clients;m jsonb;begin
 perform pro_lead_origin_owner(p_actor);select * into l from pro_lead_center_records where owner_id=p_actor and kind='manual' and id=p_lead;if not found then raise exception 'Opportunity unavailable' using errcode='P0002';end if;
 m:=pro_lead_commercial_work_mapping_read(p_actor,p_lead)->'mapping';select * into c from pro_clients where user_id=p_actor and id=l.client_id;
 if not found then raise exception 'Private customer unavailable' using errcode='42501';end if;
 if m='null'::jsonb and(l.archived or c.archived)then raise exception 'Restore the opportunity and customer before converting' using errcode='40001';end if;
 return jsonb_build_object('source',jsonb_build_object('leadId',l.id,'leadRevision',l.revision,'clientId',l.client_id),'client',jsonb_build_object('id',c.id,'name',c.name,'archived',c.archived),'service',l.title,'mapping',m);end $$;
create or replace function public.pro_lead_commercial_work_convert(p_actor uuid,p_input jsonb) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$declare aid uuid;lid uuid;wid uuid;rev integer;l pro_lead_center_records;c pro_clients;r pro_manual_lead_works;v integer;w jsonb;answer jsonb;begin
 perform pro_lead_origin_owner(p_actor);
 if jsonb_typeof(p_input)is distinct from'object'or not(p_input?&array['action','actionId','leadId','leadRevision','workId'])or exists(select 1 from jsonb_object_keys(p_input)k where k<>all(array['action','actionId','leadId','leadRevision','workId']))or p_input->>'action'is distinct from'convert'or jsonb_typeof(p_input->'actionId')is distinct from'string'or jsonb_typeof(p_input->'leadId')is distinct from'string'or jsonb_typeof(p_input->'workId')is distinct from'string'or jsonb_typeof(p_input->'leadRevision')is distinct from'number'or not coalesce(p_input->>'leadRevision'~'^[0-9]{1,10}$',false)or(p_input->>'leadRevision')::numeric not between 1 and 2147483647 then raise exception 'Invalid conversion' using errcode='22023';end if;
 aid:=(p_input->>'actionId')::uuid;lid:=(p_input->>'leadId')::uuid;wid:=(p_input->>'workId')::uuid;rev:=(p_input->>'leadRevision')::integer;
 -- Reentrant old core/customer owner lock precedes catalogue/source rows.
 perform pg_advisory_xact_lock(hashtextextended(p_actor::text,0));perform pg_advisory_xact_lock(hashtextextended('pro-manual-lead-work-action:'||p_actor::text||':'||aid::text,0));perform pg_advisory_xact_lock(hashtextextended('pro-request-pipeline-catalog:'||p_actor::text,0));perform pro_lead_origin_owner(p_actor);
 select * into r from pro_manual_lead_works where owner_id=p_actor and action_id=aid;if found then perform pro_lead_commercial_work_authorize(p_actor,aid);if r.input is distinct from p_input then raise exception 'Conversion action reused' using errcode='22023';end if;return r.result;end if;
 select * into l from pro_lead_center_records where owner_id=p_actor and kind='manual'and id=lid for update;if not found then raise exception 'Opportunity unavailable' using errcode='42501';end if;
 if exists(select 1 from pro_manual_lead_works where owner_id=p_actor and lead_id=lid)then raise exception 'Opportunity already converted' using errcode='40001';end if;
 if l.archived or l.revision<>rev then raise exception 'Opportunity changed' using errcode='40001';end if;
 if exists(select 1 from pro_work where user_id=p_actor and id=wid::text)then raise exception 'Work identity already exists' using errcode='40001';end if;
 select * into c from pro_clients where user_id=p_actor and id=l.client_id for update;if not found or c.archived then raise exception 'Choose an active private customer' using errcode='40001';end if;perform pro_lead_origin_owner(p_actor);
 select revision into v from pro_workspace_core where user_id=p_actor for update;if coalesce(v,0)>=2147483647 then raise exception 'Workspace revision exhausted' using errcode='40001';end if;
 w:=jsonb_build_object('id',wid,'client',c.name,'service',l.title,'stage','new','start','','end','','clientId',c.id,'cancelled',false);
 perform pro_patch_core(p_actor,'work',w,coalesce(v,0));perform pro_lead_origin_owner(p_actor);
 answer:=jsonb_build_object('action','convert','link',jsonb_build_object('leadId',lid,'sourceLeadRevision',rev,'sourceClientId',c.id,'workId',wid,'createdAt',now()),'work',w);
 insert into pro_manual_lead_works(owner_id,action_id,lead_id,source_lead_revision,source_client_id,source_snapshot,work_id,input,result,actor_name)values(p_actor,aid,lid,rev,c.id,pro_lead_center_manual_json(l),wid,p_input,answer,pro_team_name(p_actor));perform pro_lead_commercial_work_authorize(p_actor,aid);return answer;end $$;
create or replace function public.pro_lead_commercial_progress(p_actor uuid,p_kind text,p_id uuid)returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare l pro_lead_center_records;r jsonb;conv jsonb;automatic_stage text;effective text;current_mode text;begin
 perform pro_lead_origin_owner(p_actor);if p_kind is null or p_kind not in('manual','request')then raise exception'Invalid lead kind'using errcode='22023';end if;
 if p_kind='request'then r:=pro_lead_origin_request(p_actor,p_id);return jsonb_build_object('kind',p_kind,'id',p_id,'mode',r->'state'->'mode','automaticStageId',r->'automaticStageId','effectiveStageId',r->'effectiveStageId','conversion',null);end if;
 select*into l from pro_lead_center_records where owner_id=p_actor and kind='manual'and id=p_id;if not found then raise exception'Opportunity unavailable'using errcode='P0002';end if;
 select jsonb_build_object('actionId',m.action_id,'workId',m.work_id,'at',m.created_at)into conv from pro_manual_lead_works m join pro_work w on w.user_id=m.owner_id and w.id=m.work_id_text and w."clientId"=m.source_client_id and w."bookingClientId"is null where m.owner_id=p_actor and m.lead_kind='manual'and m.lead_id=p_id;
 automatic_stage:=case when conv is null then'new'else'won'end;current_mode:=l.stage_mode;effective:=case when current_mode='manual'then l.stage_id else automatic_stage end;
 select coalesce(reassign_to_id,effective)into effective from pro_request_pipeline_stages where owner_id=p_actor and id=effective;effective:=coalesce(effective,case when current_mode='manual'then l.stage_id else automatic_stage end);
 return jsonb_build_object('kind',p_kind,'id',p_id,'mode',current_mode,'automaticStageId',automatic_stage,'effectiveStageId',effective,'conversion',conv);end $$;
create or replace function public.pro_lead_commercial_sources(p_actor uuid,p_archived boolean,p_query text)returns table(kind text,id uuid,created_at timestamptz,effective_stage text,fingerprint text)language plpgsql stable security invoker set search_path=public,pg_temp as $$begin
 perform pro_lead_origin_owner(p_actor);if p_archived is null or p_query is null or length(p_query)>100 then raise exception'Invalid lead sources query'using errcode='22023';end if;
 return query with base as materialized(select*from pro_lead_center_sources(p_actor,p_archived,p_query))
 select b.kind,b.id,b.created_at,case when b.kind='manual'and l.stage_mode='automatic'then case when w.id is null then'new'else'won'end else b.effective_stage end,
 md5(b.fingerprint||jsonb_build_array(m.action_id,m.work_id,m.source_client_id,m.created_at,w.id)::text)
 from base b left join pro_lead_center_records l on l.owner_id=p_actor and l.kind='manual'and l.id=b.id and b.kind='manual'
 left join pro_manual_lead_works m on m.owner_id=p_actor and m.lead_kind='manual'and m.lead_id=l.id
 left join pro_work w on w.user_id=m.owner_id and w.id=m.work_id_text and w."clientId"=m.source_client_id and w."bookingClientId"is null;end $$;
create or replace function public.pro_lead_commercial_read(p_actor uuid,p_status text default 'active',p_stage text default null,p_query text default '',p_channel text default null,p_after text default null,p_snapshot text default null) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare catalog jsonb;answer jsonb;actual_token text;cursor_valid boolean;begin
 perform pro_lead_origin_owner(p_actor);catalog:=pro_lead_origin_stage_catalog(p_actor);if p_status is null or p_status not in('active','archived') or p_query is null or length(p_query)>100 or p_stage is not null and not exists(select 1 from jsonb_array_elements(catalog->'stages')s where s->>'id'=p_stage) or p_after is not null and p_after!~'^(manual|request):[a-f0-9-]{36}$' then raise exception 'Invalid lead query' using errcode='22023';end if;
 if(p_after is null)<>(p_snapshot is null)or(p_channel is not null and p_channel<>'unspecified'and pro_lead_origin_channel_json(p_actor,p_channel)is null)then raise exception'Invalid attribution filter'using errcode='22023';end if;
 with sources as materialized(select s.*,a.channel_id,coalesce(a.revision,0)origin_revision,case when s.kind='request'then exists(select 1 from pro_clients c join pro_appointment_requests r on r.owner_id=c.user_id and c.id='reservation-'||r.client_user_id::text where r.owner_id=p_actor and r.id=s.id and c.archived)else false end private_client_archived from pro_lead_commercial_sources(p_actor,p_status='archived',p_query)s left join pro_lead_origin_assignments a on a.owner_id=p_actor and a.kind=s.kind and a.id=s.id where p_channel is null or p_channel='unspecified'and a.channel_id is null or a.channel_id=p_channel),
 metadata as(select md5(p_actor::text||p_status||coalesce(p_stage,'all')||p_query||coalesce(p_channel,'all')||catalog::text||(select coalesce(jsonb_agg(to_jsonb(c)order by id)::text,'[]')from pro_lead_origin_catalog(p_actor)c)||coalesce(string_agg(jsonb_build_array(kind,id,created_at,effective_stage,fingerprint,channel_id,origin_revision,private_client_archived)::text,',' order by created_at desc,kind,id desc),''))token from sources),
 anchor as(select * from sources where kind=split_part(p_after,':',1) and id=split_part(p_after,':',2)::uuid and(p_stage is null or effective_stage=p_stage)),
 selected as materialized(select * from sources where(p_stage is null or effective_stage=p_stage) and(p_after is null or created_at<(select created_at from anchor) or created_at=(select created_at from anchor) and(kind>(select kind from anchor) or kind=(select kind from anchor) and id<(select id from anchor))) order by created_at desc,kind,id desc limit 21),
 page as(select coalesce(jsonb_agg(pro_lead_origin_item(p_actor,kind,id) order by created_at desc,kind,id desc),'[]'::jsonb)items from(select * from selected order by created_at desc,kind,id desc limit 20)v),
 counts as(select jsonb_agg(jsonb_build_object('stageId',s->>'id','count',(select count(*) from sources where effective_stage=s->>'id')) order by(s->>'position')::integer)items from jsonb_array_elements(catalog->'stages')s)
 select jsonb_build_object('catalog',catalog,'items',page.items,'counts',counts.items,'nextCursor',case when(select count(*) from selected)>20 then(select kind||':'||id::text from selected order by created_at desc,kind,id desc offset 19 limit 1)else null end,'snapshotToken',metadata.token),metadata.token,(p_after is null or exists(select 1 from anchor)) into answer,actual_token,cursor_valid from page cross join counts cross join metadata;
 if p_after is not null and(p_snapshot is null or p_snapshot<>actual_token or not cursor_valid) then raise exception 'Leads changed; refresh before continuing' using errcode='40001';end if;return jsonb_build_object('page',answer,'stages',coalesce((select jsonb_agg(pro_lead_commercial_progress(p_actor,i->>'kind',(i->>'id')::uuid)order by n)from jsonb_array_elements(answer->'items')with ordinality x(i,n)),'[]'),'context',coalesce((select jsonb_agg(pro_lead_origin_get(p_actor,i->>'kind',(i->>'id')::uuid)order by n)from jsonb_array_elements(answer->'items')with ordinality x(i,n)),'[]'));end $$;
create or replace function public.pro_lead_commercial_metrics(p_actor uuid,p_status text default'active',p_stage text default null,p_query text default'',p_from date default null,p_to date default null,p_after text default null,p_snapshot text default null)returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare answer jsonb;catalog jsonb;begin
 perform pro_lead_origin_owner(p_actor);catalog:=pro_lead_origin_stage_catalog(p_actor);
 if p_status is null or p_status not in('active','archived')or p_query is null or length(p_query)>100 or p_stage is not null and not exists(select 1 from jsonb_array_elements(catalog->'stages')s where s->>'id'=p_stage)or(p_after is null)<>(p_snapshot is null)or p_from is not null and p_from not between date'1900-01-01'and date'2100-12-31'or p_to is not null and p_to not between date'1900-01-01'and date'2100-12-31'or p_from>p_to then raise exception'Invalid metrics query'using errcode='22023';end if;
 with sources as materialized(select s.*,a.channel_id,coalesce(a.revision,0)origin_revision,case when s.kind='request'then exists(select 1 from pro_clients c join pro_appointment_requests r on r.owner_id=c.user_id and c.id='reservation-'||r.client_user_id::text where r.owner_id=p_actor and r.id=s.id and c.archived)else false end private_client_archived from pro_lead_commercial_sources(p_actor,p_status='archived',p_query)s left join pro_lead_origin_assignments a on a.owner_id=p_actor and a.kind=s.kind and a.id=s.id where(p_stage is null or s.effective_stage=p_stage)and(p_from is null or(s.created_at at time zone'America/Costa_Rica')::date>=p_from)and(p_to is null or(s.created_at at time zone'America/Costa_Rica')::date<=p_to)),
 groups as(select channel_id,count(*)filter(where kind='manual')manual,count(*)filter(where kind='request')request,count(*)total,count(*)filter(where effective_stage='won')won from sources group by channel_id),
 rows as(select 'unspecified'::text id,'0'::text ordering,null::text channel_id,coalesce(g.manual,0)manual,coalesce(g.request,0)request,coalesce(g.total,0)total,coalesce(g.won,0)won from(select 1)dummy left join groups g on g.channel_id is null union all select channel_id,'1:'||channel_id,channel_id,manual,request,total,won from groups where channel_id is not null),
 metadata as(select md5(p_actor::text||p_status||coalesce(p_stage,'all')||p_query||coalesce(p_from::text,'')||coalesce(p_to::text,'')||catalog::text||(select coalesce(jsonb_agg(to_jsonb(c)order by id)::text,'[]')from pro_lead_origin_catalog(p_actor)c)||coalesce(jsonb_agg(jsonb_build_array(kind,id,fingerprint,effective_stage,channel_id,origin_revision,private_client_archived)order by created_at desc,kind,id desc)::text,'[]'))token from sources),
 page as(select*from rows where p_after is null or ordering>(case when p_after='unspecified'then'0'else'1:'||p_after end)order by ordering limit 21)
 select jsonb_build_object('fingerprint',(select token from metadata),'items',coalesce((select jsonb_agg(jsonb_build_object('channel',pro_lead_origin_channel_json(p_actor,channel_id),'manual',manual,'request',request,'total',total,'won',won)order by ordering)from(select*from page order by ordering limit 20)p),'[]'),'totals',(select jsonb_build_object('manual',count(*)filter(where kind='manual'),'request',count(*)filter(where kind='request'),'total',count(*),'won',count(*)filter(where effective_stage='won'))from sources),'nextCursor',case when(select count(*)from page)>20 then(select id from page order by ordering offset 19 limit 1)else null end,'validCursor',p_after is null or exists(select 1 from rows where id=p_after))into answer;
 if p_after is not null and(p_snapshot is distinct from answer->>'fingerprint'or not(answer->>'validCursor')::boolean)then raise exception'Metrics changed'using errcode='40001';end if;return answer-'validCursor';end $$;
create or replace function public.pro_lead_commercial_detail(p_actor uuid,p_kind text,p_id uuid)returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$select jsonb_build_object('detail',pro_lead_private_core_detail(p_actor,p_kind,p_id),'stage',pro_lead_commercial_progress(p_actor,p_kind,p_id))$$;
-- Only new functions are granted. No old function, table, trigger or row changes.
do $$declare f record;begin for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname like'pro_lead_commercial_%'loop execute format('revoke all on function %s from public,anon,authenticated',f.signature);execute format('grant execute on function %s to service_role',f.signature);end loop;end $$;
commit;
notify pgrst,'reload schema';

-- ===== private-work-tools-access-local.sql =====
-- LOCAL PRO ONLY. Deliberate allowlisted correction to seven owner-private RPCs.
-- Payloads, signatures, receipts, histories, tables and actor/work scope remain
-- unchanged. Public appointment eligibility and all team/client readers stay intact.
begin;
create or replace function public.pro_private_work_tools_enabled(p_actor uuid)returns boolean language sql volatile security invoker set search_path=public,pg_temp as $$
 -- Single Pro entitlement rule (pro_entitled, pro-entitled-draft.sql); signature and volatility kept.
 select public.pro_entitled(p_actor);
$$;
create or replace function public.pro_work_tasks_read(p_actor uuid,p_work text,p_status text default 'open',p_after uuid default null,p_archived boolean default false,p_task uuid default null) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare task public.pro_work_tasks;items jsonb;hist jsonb;cursor_id uuid;cursor_due date;open_count integer;done_count integer;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_work is null or length(p_work) not between 1 and 160 or p_status is null or p_status not in('open','done','all') or p_archived is null then raise exception 'Invalid task query' using errcode='22023';end if;
 if not exists(select 1 from public.pro_work where user_id=p_actor and id=p_work) then return null;end if;
 if p_task is not null then
  select * into task from public.pro_work_tasks where owner_id=p_actor and work_id=p_work and id=p_task;
  if not found then return null;end if;
  select coalesce(jsonb_agg(x.content order by x.revision desc),'[]'::jsonb) into hist from (
   select (h.after_task->>'revision')::integer as revision,jsonb_build_object('actionId',h.action_id,'at',h.at,'action',h.action,'before',h.before_task,'after',h.after_task) as content
   from public.pro_work_task_history h where h.owner_id=p_actor and h.work_id=p_work and h.task_id=p_task order by (h.after_task->>'revision')::integer desc limit 20
  ) x;
  return jsonb_build_object('task',public.pro_work_task_json(task),'history',hist);
 end if;
 if p_after is not null then
  -- Round 7B: the list follows the plan (planned start), then the due date; same key for the cursor.
  select coalesce(sp.planned_start,t.due_date,date '9999-12-31') into cursor_due from public.pro_work_tasks t left join public.pro_work_schedule_plans sp on sp.owner_id=t.owner_id and sp.work_id=t.work_id and sp.task_id=t.id where t.owner_id=p_actor and t.work_id=p_work and t.id=p_after;
  if not found then raise exception 'Invalid task cursor' using errcode='22023';end if;
 end if;
 select count(*) filter(where status='open'),count(*) filter(where status='done') into open_count,done_count from public.pro_work_tasks where owner_id=p_actor and work_id=p_work and not archived;
 select coalesce(jsonb_agg(public.pro_work_task_json(t.task) order by t.k,t.id),'[]'::jsonb) into items from (
  select x as task,x.id,coalesce(sp.planned_start,x.due_date,date '9999-12-31') k from public.pro_work_tasks x left join public.pro_work_schedule_plans sp on sp.owner_id=x.owner_id and sp.work_id=x.work_id and sp.task_id=x.id
  where x.owner_id=p_actor and x.work_id=p_work and x.archived=p_archived and (p_status='all' or x.status=p_status) and (p_after is null or (coalesce(sp.planned_start,x.due_date,date '9999-12-31'),x.id)>(cursor_due,p_after)) order by 3,x.id limit 21
 ) t;
 if jsonb_array_length(items)>20 then cursor_id:=(items->19->>'id')::uuid;items:=items-20;end if;
 return jsonb_build_object('workId',p_work,'items',items,'nextCursor',cursor_id,'counts',jsonb_build_object('open',open_count,'done',done_count));
end $$;
create or replace function public.pro_work_tasks_mutate(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare wid text;tid uuid;aid uuid;act text;rev integer;keys text[];receipt public.pro_work_task_actions;task public.pro_work_tasks;before_json jsonb;after_json jsonb;result jsonb;due date;task_title text;task_details text;task_assignee text;task_exists boolean;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input) is distinct from 'object' then raise exception 'Invalid task' using errcode='22023';end if;
 act:=p_input->>'action';wid:=p_input->>'workId';
 if act is null or act not in('create','update','complete','reopen','archive','restore') or jsonb_typeof(p_input->'workId') is distinct from 'string' or length(wid) not between 1 and 160
 or jsonb_typeof(p_input->'taskId') is distinct from 'string' or jsonb_typeof(p_input->'actionId') is distinct from 'string'
 or jsonb_typeof(p_input->'revision') is distinct from 'number' or not coalesce((p_input->>'revision')~'^[0-9]{1,10}$',false)
 then raise exception 'Invalid task identity' using errcode='22023';end if;
 if (p_input->>'revision')::numeric>2147483646 then raise exception 'Invalid revision' using errcode='22023';end if;
 tid:=(p_input->>'taskId')::uuid;aid:=(p_input->>'actionId')::uuid;rev:=(p_input->>'revision')::integer;
 select array_agg(key order by key) into keys from jsonb_object_keys(p_input) key;
 if act in('create','update') then
  if keys<>array['action','actionId','assignee','details','dueDate','revision','taskId','title','workId']
   or jsonb_typeof(p_input->'title') is distinct from 'string' or jsonb_typeof(p_input->'details') is distinct from 'string' or jsonb_typeof(p_input->'assignee') is distinct from 'string'
   or not coalesce(jsonb_typeof(p_input->'dueDate') in('null','string'),false)
  then raise exception 'Invalid task fields' using errcode='22023';end if;
  task_title:=btrim(p_input->>'title');task_details:=btrim(p_input->>'details');task_assignee:=btrim(p_input->>'assignee');
  if length(task_title) not between 1 and 160 or length(task_details)>2000 or length(task_assignee)>160 then raise exception 'Invalid task text' using errcode='22023';end if;
  if p_input->'dueDate'<>'null'::jsonb then
   if not coalesce((p_input->>'dueDate')~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$',false) then raise exception 'Invalid date' using errcode='22023';end if;
   due:=(p_input->>'dueDate')::date;
   if due<date '1900-01-01' or due>date '2100-12-31' or to_char(due,'YYYY-MM-DD')<>p_input->>'dueDate' then raise exception 'Invalid date' using errcode='22023';end if;
  end if;
 else
  if keys<>array['action','actionId','revision','taskId','workId'] then raise exception 'Unexpected task fields' using errcode='22023';end if;
 end if;
 -- Action identity is serialized first, including concurrent retries for two jobs.
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false)or not exists(select 1 from public.pro_work where user_id=p_actor and id=wid)then raise exception 'Forbidden' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-work-task-action:'||p_actor::text||':'||aid::text,0));
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false)or not exists(select 1 from public.pro_work where user_id=p_actor and id=wid)then raise exception 'Forbidden' using errcode='42501';end if;
 select * into receipt from public.pro_work_task_actions where actor_id=p_actor and action_id=aid;
 if found then
  if receipt.input is distinct from p_input then raise exception 'Action identity reused with different payload' using errcode='22023';end if;
  return receipt.result;
 end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-work-tasks:'||p_actor::text||':'||wid,0));
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false)or not exists(select 1 from public.pro_work where user_id=p_actor and id=wid)then raise exception 'Forbidden' using errcode='42501';end if;
 select * into task from public.pro_work_tasks where owner_id=p_actor and id=tid for update;task_exists:=found;
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false)or not exists(select 1 from public.pro_work where user_id=p_actor and id=wid)then raise exception 'Forbidden' using errcode='42501';end if;
 if act='create' then
  if rev<>0 then raise exception 'Create requires zero revision' using errcode='22023';end if;
  if task_exists then raise exception 'Task identity already exists' using errcode='22023';end if;
  if (select count(*) from public.pro_work_tasks where owner_id=p_actor and work_id=wid)>=500 then raise exception 'Task limit reached' using errcode='54000';end if;
  insert into public.pro_work_tasks(owner_id,work_id,id,title,details,due_date,assignee) values(p_actor,wid,tid,task_title,task_details,due,task_assignee) returning * into task;
 else
  if not task_exists or task.work_id<>wid then raise exception 'Forbidden' using errcode='42501';end if;
  if rev<>task.revision then raise exception 'Task changed' using errcode='40001';end if;
  before_json:=public.pro_work_task_json(task);
  if act='update' then
   if task.archived then raise exception 'Restore task before editing' using errcode='22023';end if;
   update public.pro_work_tasks set title=task_title,details=task_details,due_date=due,assignee=task_assignee,revision=revision+1,updated_at=now() where owner_id=p_actor and id=tid returning * into task;
  elsif act in('complete','reopen') then
   if task.archived or (act='complete' and task.status<>'open') or (act='reopen' and task.status<>'done') then raise exception 'Invalid task transition' using errcode='22023';end if;
   update public.pro_work_tasks set status=case when act='complete' then 'done' else 'open' end,revision=revision+1,updated_at=now() where owner_id=p_actor and id=tid returning * into task;
  elsif act in('archive','restore') then
   if task.archived=(act='archive') then raise exception 'Invalid archive transition' using errcode='22023';end if;
   update public.pro_work_tasks set archived=(act='archive'),revision=revision+1,updated_at=now() where owner_id=p_actor and id=tid returning * into task;
  end if;
 end if;
 after_json:=public.pro_work_task_json(task);result:=jsonb_build_object('task',after_json);
 insert into public.pro_work_task_history(owner_id,work_id,task_id,action_id,action,before_task,after_task) values(p_actor,wid,tid,aid,act,before_json,after_json);
 insert into public.pro_work_task_actions(actor_id,action_id,input,result) values(p_actor,aid,p_input,result);
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false)or not exists(select 1 from public.pro_work where user_id=p_actor and id=wid)then raise exception 'Forbidden' using errcode='42501';end if;
 return result;
end $$;
create or replace function public.pro_work_updates_read(p_actor uuid,p_work text,p_after uuid default null,p_entry uuid default null) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare entry public.pro_work_updates;items jsonb;hist jsonb;cursor_time timestamptz;cursor_id uuid;can_share boolean;recipient uuid;recipient_name text;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_work is null or length(p_work) not between 1 and 160 or p_after is not null and p_entry is not null then raise exception 'Invalid progress query' using errcode='22023';end if;
 if not exists(select 1 from public.pro_work where user_id=p_actor and id=p_work) then return null;end if;
 can_share:=public.pro_work_update_can_share(p_actor,p_work);
 if can_share then
  select ar.client_user_id,ar.client_name into recipient,recipient_name from public.pro_appointment_requests ar join public.profiles c on c.id=ar.client_user_id
   where ar.owner_id=p_actor and ar.work_id=p_work and ar.status in('confirmed','completed') and not coalesce(c.is_disabled,false);
 end if;
 if p_entry is not null then
  select * into entry from public.pro_work_updates where owner_id=p_actor and work_id=p_work and id=p_entry;
  if not found then return null;end if;
  select coalesce(jsonb_agg(x.content order by x.revision desc),'[]'::jsonb) into hist from (
   select (h.after_entry->>'revision')::integer as revision,jsonb_build_object('actionId',h.action_id,'action',h.action,'at',h.at,'before',h.before_entry,'after',h.after_entry) as content
   from public.pro_work_update_history h where h.owner_id=p_actor and h.work_id=p_work and h.entry_id=p_entry order by (h.after_entry->>'revision')::integer desc limit 20
  ) x;
  return jsonb_build_object('entry',public.pro_work_update_json(entry),'history',hist,'canShare',can_share,'recipientId',recipient,'recipientName',recipient_name);
 end if;
 if p_after is not null then
  select created_at into cursor_time from public.pro_work_updates where owner_id=p_actor and work_id=p_work and id=p_after;
  if not found then raise exception 'Invalid progress cursor' using errcode='22023';end if;
 end if;
 select coalesce(jsonb_agg(public.pro_work_update_json(e::public.pro_work_updates) order by e.created_at desc,e.id desc),'[]'::jsonb) into items from (
  select * from public.pro_work_updates where owner_id=p_actor and work_id=p_work and (p_after is null or (created_at,id)<(cursor_time,p_after)) order by created_at desc,id desc limit 21
 ) e;
 if jsonb_array_length(items)>20 then cursor_id:=(items->19->>'id')::uuid;items:=items-20;end if;
 return jsonb_build_object('workId',p_work,'items',items,'nextCursor',cursor_id,'canShare',can_share,'recipientId',recipient,'recipientName',recipient_name);
end $$;
create or replace function public.pro_work_updates_mutate(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare wid text;eid uuid;aid uuid;act text;rev integer;keys text[];receipt public.pro_work_update_actions;entry public.pro_work_updates;w public.pro_work;r public.pro_appointment_requests;before_json jsonb;after_json jsonb;result jsonb;entry_title text;entry_text text;recipient uuid;publication integer;entry_exists boolean;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input) is distinct from 'object' then raise exception 'Invalid progress' using errcode='22023';end if;
 act:=p_input->>'action';wid:=p_input->>'workId';
 if act is null or act not in('create','update','publish') or jsonb_typeof(p_input->'workId') is distinct from 'string' or length(wid) not between 1 and 160
 or jsonb_typeof(p_input->'entryId') is distinct from 'string' or jsonb_typeof(p_input->'actionId') is distinct from 'string'
 or jsonb_typeof(p_input->'revision') is distinct from 'number' or not coalesce((p_input->>'revision')~'^[0-9]{1,10}$',false) then raise exception 'Invalid progress identity' using errcode='22023';end if;
 if (p_input->>'revision')::numeric>2147483646 then raise exception 'Invalid revision' using errcode='22023';end if;
 eid:=(p_input->>'entryId')::uuid;aid:=(p_input->>'actionId')::uuid;rev:=(p_input->>'revision')::integer;
 select array_agg(key order by key) into keys from jsonb_object_keys(p_input) key;
 if act in('create','update') then
  if keys<>array['action','actionId','entryId','revision','text','title','workId'] or jsonb_typeof(p_input->'title') is distinct from 'string' or jsonb_typeof(p_input->'text') is distinct from 'string' then raise exception 'Invalid progress fields' using errcode='22023';end if;
  entry_title:=btrim(p_input->>'title');entry_text:=btrim(p_input->>'text');
  if length(entry_title) not between 1 and 160 or length(entry_text) not between 1 and 2000 then raise exception 'Invalid progress text' using errcode='22023';end if;
 else
  if keys<>array['action','actionId','entryId','recipientId','revision','workId'] or jsonb_typeof(p_input->'recipientId') is distinct from 'string' then raise exception 'Unexpected progress fields' using errcode='22023';end if;
  recipient:=(p_input->>'recipientId')::uuid;
 end if;
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false)or not exists(select 1 from public.pro_work where user_id=p_actor and id=wid)then raise exception 'Forbidden' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-work-update-action:'||p_actor::text||':'||aid::text,0));
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false)or not exists(select 1 from public.pro_work where user_id=p_actor and id=wid)then raise exception 'Forbidden' using errcode='42501';end if;
 select * into receipt from public.pro_work_update_actions where actor_id=p_actor and action_id=aid;
 if found then
  if receipt.input is distinct from p_input then raise exception 'Action identity reused with different payload' using errcode='22023';end if;
  return receipt.result;
 end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-work-updates:'||p_actor::text||':'||wid,0));
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false)or not exists(select 1 from public.pro_work where user_id=p_actor and id=wid)then raise exception 'Forbidden' using errcode='42501';end if;
 -- Match appointment cancel/reschedule ordering: request first, then work.
 -- A private create/update never locks the request. Receipt replay above never
 -- re-targets an already committed publication to a newly linked customer.
 if act='publish' then
  select ar.* into r from public.pro_appointment_requests ar where ar.owner_id=p_actor and ar.work_id=wid for share of ar;
  if not found then raise exception 'No linked customer' using errcode='42501';end if;
  if not coalesce(public.pro_private_work_tools_enabled(p_actor),false)or not exists(select 1 from public.pro_work where user_id=p_actor and id=wid)then raise exception 'Forbidden' using errcode='42501';end if;
 end if;
 select * into w from public.pro_work where user_id=p_actor and id=wid for update;
 if not found then raise exception 'Forbidden' using errcode='42501';end if;
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false)or not exists(select 1 from public.pro_work where user_id=p_actor and id=wid)then raise exception 'Forbidden' using errcode='42501';end if;
 select * into entry from public.pro_work_updates where owner_id=p_actor and id=eid for update;entry_exists:=found;
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false)or not exists(select 1 from public.pro_work where user_id=p_actor and id=wid)then raise exception 'Forbidden' using errcode='42501';end if;
 if act='create' then
  if rev<>0 then raise exception 'Create requires zero revision' using errcode='22023';end if;
  if entry_exists then raise exception 'Progress identity already exists' using errcode='22023';end if;
  if (select count(*) from public.pro_work_updates where owner_id=p_actor and work_id=wid)>=500 then raise exception 'Progress entry limit' using errcode='54000';end if;
  insert into public.pro_work_updates(owner_id,work_id,id,title,text) values(p_actor,wid,eid,entry_title,entry_text) returning * into entry;
 else
  if not entry_exists or entry.work_id<>wid then raise exception 'Forbidden' using errcode='42501';end if;
  if rev<>entry.revision then raise exception 'Progress changed' using errcode='40001';end if;
  before_json:=public.pro_work_update_json(entry);
  if act='update' then
   update public.pro_work_updates set title=entry_title,text=entry_text,revision=revision+1,updated_at=now() where owner_id=p_actor and id=eid returning * into entry;
  else
   if entry.published_revision is not distinct from entry.revision then raise exception 'No private changes to share' using errcode='22023';end if;
   if coalesce(w.cancelled,false) then raise exception 'Cancelled job cannot share progress' using errcode='42501';end if;
   if r.client_user_id<>recipient then raise exception 'The share recipient changed' using errcode='40001';end if;
   if r.status not in('confirmed','completed') or not exists(select 1 from public.profiles where id=r.client_user_id and not coalesce(is_disabled,false)) then raise exception 'No linked confirmed customer' using errcode='42501';end if;
   update public.pro_work_updates set revision=revision+1,published_revision=revision+1,updated_at=now() where owner_id=p_actor and id=eid returning * into entry;
   select coalesce(max(version),0)+1 into publication from public.pro_work_update_versions where owner_id=p_actor and entry_id=eid;
   insert into public.pro_work_update_versions(owner_id,work_id,entry_id,version,entry_revision,client_user_id,recipient_name,title,text,service,entry_created_at)
    values(p_actor,wid,eid,publication,entry.revision,r.client_user_id,r.client_name,entry.title,entry.text,w.service,entry.created_at);
  end if;
 end if;
 after_json:=public.pro_work_update_json(entry);result:=jsonb_build_object('entry',after_json);
 insert into public.pro_work_update_history(owner_id,work_id,entry_id,action_id,action,before_entry,after_entry) values(p_actor,wid,eid,aid,act,before_json,after_json);
 insert into public.pro_work_update_actions(actor_id,action_id,input,result) values(p_actor,aid,p_input,result);
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false)or not exists(select 1 from public.pro_work where user_id=p_actor and id=wid)then raise exception 'Forbidden' using errcode='42501';end if;
 return result;
end $$;
create or replace function public.pro_task_center_read(p_actor uuid,p_status text default 'open',p_timing text default 'all',p_query text default '',p_after uuid default null) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare today_cr date:=(now() at time zone 'America/Costa_Rica')::date;needle text;cursor_due date;cursor_id uuid;items jsonb;open_count integer;done_count integer;overdue_count integer;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_status is null or p_status not in('open','done','all') or p_timing is null or p_timing not in('all','overdue','today','upcoming') or p_query is null or length(p_query)>100 then raise exception 'Invalid task-center query' using errcode='22023';end if;
 needle:=lower(btrim(p_query));
 -- Literal substring matching: percent/underscore never become SQL wildcards.
 select count(*) filter(where t.status='open'),count(*) filter(where t.status='done'),count(*) filter(where t.status='open' and t.due_date<today_cr)
 into open_count,done_count,overdue_count from public.pro_work_tasks t join public.pro_work w on w.user_id=t.owner_id and w.id=t.work_id
 where t.owner_id=p_actor and not t.archived and (needle='' or position(needle in lower(t.title))>0 or position(needle in lower(t.details))>0 or position(needle in lower(t.assignee))>0 or position(needle in lower(w.service))>0 or position(needle in lower(w.client))>0);
 if p_after is not null then
  select coalesce(t.due_date,date '9999-12-31') into cursor_due from public.pro_work_tasks t join public.pro_work w on w.user_id=t.owner_id and w.id=t.work_id
  where t.owner_id=p_actor and t.id=p_after and not t.archived and (p_status='all' or t.status=p_status)
  and (needle='' or position(needle in lower(t.title))>0 or position(needle in lower(t.details))>0 or position(needle in lower(t.assignee))>0 or position(needle in lower(w.service))>0 or position(needle in lower(w.client))>0)
  and case p_timing when 'all' then true when 'overdue' then t.status='open' and t.due_date<today_cr when 'today' then t.due_date=today_cr else t.due_date>today_cr end;
  if not found then raise exception 'Task-center cursor changed; refresh the list' using errcode='22023';end if;
 end if;
 select coalesce(jsonb_agg(jsonb_build_object('task',public.pro_work_task_json(x.task),'work',jsonb_build_object('id',x.work_id,'service',x.service,'client',x.client,'stage',x.stage,'cancelled',x.cancelled)) order by (x.task).due_date asc nulls last,(x.task).id),'[]'::jsonb) into items from (
  select t as task,w.id as work_id,w.service,w.client,w.stage,coalesce(w.cancelled,false) as cancelled
  from public.pro_work_tasks t join public.pro_work w on w.user_id=t.owner_id and w.id=t.work_id
  where t.owner_id=p_actor and not t.archived and (p_status='all' or t.status=p_status)
  and (needle='' or position(needle in lower(t.title))>0 or position(needle in lower(t.details))>0 or position(needle in lower(t.assignee))>0 or position(needle in lower(w.service))>0 or position(needle in lower(w.client))>0)
  and case p_timing when 'all' then true when 'overdue' then t.status='open' and t.due_date<today_cr when 'today' then t.due_date=today_cr else t.due_date>today_cr end
  and (p_after is null or (coalesce(t.due_date,date '9999-12-31'),t.id)>(cursor_due,p_after))
  order by t.due_date asc nulls last,t.id limit 21
 ) x;
 if jsonb_array_length(items)>20 then cursor_id:=(items->19->'task'->>'id')::uuid;items:=items-20;end if;
 return jsonb_build_object('items',items,'nextCursor',cursor_id,'counts',jsonb_build_object('open',open_count,'done',done_count,'overdue',overdue_count));
end $$;
create or replace function public.pro_task_center_jobs_read(p_actor uuid,p_query text default '',p_after text default null) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare needle text;items jsonb;cursor_id text;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_query is null or length(p_query)>100 or p_after is not null and length(p_after) not between 1 and 160 then raise exception 'Invalid job-picker query' using errcode='22023';end if;
 needle:=lower(btrim(p_query));
 if p_after is not null and not exists(select 1 from public.pro_work where user_id=p_actor and id=p_after and not coalesce(cancelled,false)
 and (needle='' or position(needle in lower(service))>0 or position(needle in lower(client))>0)) then raise exception 'Job-picker cursor changed; refresh the list' using errcode='22023';end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',w.id,'service',w.service,'client',w.client,'start',w.start,'stage',w.stage,'cancelled',false) order by w.id),'[]'::jsonb) into items from (
  select id,service,client,start,stage from public.pro_work where user_id=p_actor and not coalesce(cancelled,false)
  and (needle='' or position(needle in lower(service))>0 or position(needle in lower(client))>0) and (p_after is null or id>p_after) order by id limit 21
 ) w;
 if jsonb_array_length(items)>20 then cursor_id:=items->19->>'id';items:=items-20;end if;
 return jsonb_build_object('items',items,'nextCursor',cursor_id);
end $$;
create or replace function public.pro_task_center_planning_read(p_actor uuid,p_status text default 'open',p_timing text default 'all',p_query text default '',p_after uuid default null) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare today_cr date:=(now() at time zone 'America/Costa_Rica')::date;needle text;cursor_due date;cursor_id uuid;items jsonb;open_count integer;done_count integer;overdue_count integer;metadata jsonb;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_status is null or p_status not in('open','done','all') or p_timing is null or p_timing not in('all','overdue','today','upcoming') or p_query is null or length(p_query)>100 then raise exception 'Invalid task-center query' using errcode='22023';end if;
 needle:=lower(btrim(p_query));
 -- Literal substring matching: percent/underscore never become SQL wildcards.
 select count(*) filter(where t.status='open'),count(*) filter(where t.status='done'),count(*) filter(where t.status='open' and t.due_date<today_cr)
 into open_count,done_count,overdue_count from public.pro_work_tasks t join public.pro_work w on w.user_id=t.owner_id and w.id=t.work_id
 where t.owner_id=p_actor and not t.archived and public.pro_task_center_planning_matches(t,w,needle);
 if p_after is not null then
  select coalesce(t.due_date,date '9999-12-31') into cursor_due from public.pro_work_tasks t join public.pro_work w on w.user_id=t.owner_id and w.id=t.work_id
  where t.owner_id=p_actor and t.id=p_after and not t.archived and (p_status='all' or t.status=p_status)
  and public.pro_task_center_planning_matches(t,w,needle)
  and case p_timing when 'all' then true when 'overdue' then t.status='open' and t.due_date<today_cr when 'today' then t.due_date=today_cr else t.due_date>today_cr end;
  if not found then raise exception 'Task-center cursor changed; refresh the list' using errcode='22023';end if;
 end if;
 select coalesce(jsonb_agg(jsonb_build_object('task',public.pro_work_task_json(x.task),'work',jsonb_build_object('id',x.work_id,'service',x.service,'client',x.client,'stage',x.stage,'cancelled',x.cancelled)) order by (x.task).due_date asc nulls last,(x.task).id),'[]'::jsonb) into items from (
  select t as task,w.id as work_id,w.service,w.client,w.stage,coalesce(w.cancelled,false) as cancelled
  from public.pro_work_tasks t join public.pro_work w on w.user_id=t.owner_id and w.id=t.work_id
  where t.owner_id=p_actor and not t.archived and (p_status='all' or t.status=p_status)
  and public.pro_task_center_planning_matches(t,w,needle)
  and case p_timing when 'all' then true when 'overdue' then t.status='open' and t.due_date<today_cr when 'today' then t.due_date=today_cr else t.due_date>today_cr end
  and (p_after is null or (coalesce(t.due_date,date '9999-12-31'),t.id)>(cursor_due,p_after))
  order by t.due_date asc nulls last,t.id limit 21
 ) x;
 if jsonb_array_length(items)>20 then cursor_id:=(items->19->'task'->>'id')::uuid;items:=items-20;end if;
 -- Resolve metadata from this exact bounded page inside the same SQL snapshot.
 select coalesce(jsonb_agg(public.pro_task_center_planning_context(t) order by i.ordinality),'[]'::jsonb) into metadata
 from jsonb_array_elements(items) with ordinality i(entry,ordinality)
 join public.pro_work_tasks t on t.owner_id=p_actor and t.id=(i.entry->'task'->>'id')::uuid and t.work_id=(i.entry->'task'->>'workId');
 return jsonb_build_object('page',jsonb_build_object('items',items,'nextCursor',cursor_id,'counts',jsonb_build_object('open',open_count,'done',done_count,'overdue',overdue_count)),'context',metadata);
end $$;
-- Exact allowlist, rather than broad grants over similarly named functions.
revoke all on function public.pro_private_work_tools_enabled(uuid),public.pro_work_tasks_read(uuid,text,text,uuid,boolean,uuid),public.pro_work_tasks_mutate(uuid,jsonb),public.pro_work_updates_read(uuid,text,uuid,uuid),public.pro_work_updates_mutate(uuid,jsonb),public.pro_task_center_read(uuid,text,text,text,uuid),public.pro_task_center_jobs_read(uuid,text,text),public.pro_task_center_planning_read(uuid,text,text,text,uuid)from public,anon,authenticated;
grant execute on function public.pro_private_work_tools_enabled(uuid),public.pro_work_tasks_read(uuid,text,text,uuid,boolean,uuid),public.pro_work_tasks_mutate(uuid,jsonb),public.pro_work_updates_read(uuid,text,uuid,uuid),public.pro_work_updates_mutate(uuid,jsonb),public.pro_task_center_read(uuid,text,text,text,uuid),public.pro_task_center_jobs_read(uuid,text,text),public.pro_task_center_planning_read(uuid,text,text,text,uuid)to service_role;
commit;
notify pgrst,'reload schema';

-- ===== private-lead-quote-read-local.sql =====
-- LOCAL Pro only: private read gateway. No issuer fabrication, quote writes or old function replacement.
begin;
create or replace function public.pro_private_lead_quote_context(p_actor uuid,p_lead uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare l pro_lead_center_records;c pro_clients;begin
 if not coalesce(pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;select * into l from pro_lead_center_records where owner_id=p_actor and kind='manual' and id=p_lead;if not found then raise exception 'Opportunity unavailable' using errcode='P0002';end if;if l.archived then raise exception 'Restore the opportunity before creating a quote' using errcode='40001';end if;
 select * into c from pro_clients where user_id=p_actor and id=l.client_id;if not found or c.archived then raise exception 'Choose an active private customer' using errcode='40001';end if;
 return jsonb_build_object('source',jsonb_build_object('leadId',l.id,'leadRevision',l.revision,'clientId',l.client_id),'client',jsonb_build_object('id',c.id,'name',c.name,'email',c.email,'phone',c.phone,'identification',c.identification,'address',c.address,'tradeName',c."tradeName"),'title',l.title,'currency','CRC');end $$;
create or replace function public.pro_private_lead_quote_authorize(p_actor uuid,p_action uuid) returns void language plpgsql security invoker set search_path=public,pg_temp as $$declare r pro_manual_lead_quotes;begin
 if not coalesce(pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;select * into r from pro_manual_lead_quotes where owner_id=p_actor and action_id=p_action;if not found then raise exception 'Origin receipt unavailable' using errcode='42501';end if;
 if not exists(select 1 from pro_lead_center_records where owner_id=p_actor and kind='manual' and id=r.lead_id) or not exists(select 1 from quotes q join professionals p on p.id=q.professional_id and p.profile_id=p_actor join pro_quote_links l on l.user_id=p_actor and l."quoteId"=q.id::text and l."clientId"=r.source_client_id where q.id=r.quote_id and q.client_id is null and q.project_id is null and q.proposal_id is null) then raise exception 'Origin ownership unavailable' using errcode='42501';end if;end $$;
create or replace function public.pro_private_lead_quote_action_read(p_actor uuid,p_action uuid) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$declare r pro_manual_lead_quotes;begin
 if not coalesce(pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;select * into r from pro_manual_lead_quotes where owner_id=p_actor and action_id=p_action;if not found then return jsonb_build_object('receipt',null);end if;perform pro_private_lead_quote_authorize(p_actor,p_action);return jsonb_build_object('receipt',jsonb_build_object('input',r.input,'result',r.result));end $$;
create or replace function public.pro_private_lead_quote_list(p_actor uuid,p_lead uuid,p_after uuid default null) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare anchor_time timestamptz;items jsonb;cursor_id uuid;begin
 if not coalesce(pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;if not exists(select 1 from pro_lead_center_records where owner_id=p_actor and kind='manual' and id=p_lead) then raise exception 'Opportunity unavailable' using errcode='P0002';end if;
 if p_after is not null then select r.created_at into anchor_time from pro_manual_lead_quotes r join quotes q on q.id=r.quote_id and q.deleted_at is null join professionals p on p.id=q.professional_id and p.profile_id=p_actor where r.owner_id=p_actor and r.lead_id=p_lead and r.quote_id=p_after;if not found then raise exception 'Quotation cursor changed' using errcode='40001';end if;end if;
 select coalesce(jsonb_agg(jsonb_build_object('link',r.result->'link','quote',pro_manual_lead_quote_dto(to_jsonb(q)||jsonb_build_object('professional_name',r.result->'quote'->'professional_name','professional_full_name',r.result->'quote'->'professional_full_name')))order by r.created_at desc,r.quote_id desc),'[]'::jsonb)into items from(select l.* from pro_manual_lead_quotes l join quotes d on d.id=l.quote_id and d.deleted_at is null join professionals p on p.id=d.professional_id and p.profile_id=p_actor where l.owner_id=p_actor and l.lead_id=p_lead and(p_after is null or(l.created_at,l.quote_id)<(anchor_time,p_after))order by l.created_at desc,l.quote_id desc limit 21)r join quotes q on q.id=r.quote_id;
 if jsonb_array_length(items)>20 then cursor_id:=(items->19->'quote'->>'id')::uuid;items:=items-20;end if;return jsonb_build_object('items',items,'nextCursor',cursor_id);end $$;
create or replace function public.pro_private_lead_quote_capability(p_actor uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$begin
 if not coalesce(pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if exists(select 1 from professionals where profile_id=p_actor and not coalesce(is_banned,false)) then return jsonb_build_object('issuerKind','professional','canCreateLegacy',true,'reason',null);end if;
 return jsonb_build_object('issuerKind',null,'canCreateLegacy',false,'reason','issuer_required');end $$;
revoke all on function public.pro_private_lead_quote_context(uuid,uuid) from public,anon,authenticated;
grant execute on function public.pro_private_lead_quote_context(uuid,uuid) to service_role;
revoke all on function public.pro_private_lead_quote_authorize(uuid,uuid) from public,anon,authenticated;
grant execute on function public.pro_private_lead_quote_authorize(uuid,uuid) to service_role;
revoke all on function public.pro_private_lead_quote_action_read(uuid,uuid) from public,anon,authenticated;
grant execute on function public.pro_private_lead_quote_action_read(uuid,uuid) to service_role;
revoke all on function public.pro_private_lead_quote_list(uuid,uuid,uuid) from public,anon,authenticated;
grant execute on function public.pro_private_lead_quote_list(uuid,uuid,uuid) to service_role;
revoke all on function public.pro_private_lead_quote_capability(uuid) from public,anon,authenticated;
grant execute on function public.pro_private_lead_quote_capability(uuid) to service_role;
commit;
notify pgrst, 'reload schema';

-- ===== private-work-plan-access-local.sql =====
-- LOCAL Pro only. Sole allowlisted replacement: owner plan authorization.
-- Team context/client readers and all writers remain unchanged. This shared guard
-- is also consumed by owner DailyLogs/file/discussion/template helpers; their
-- additional direct public-availability guards are intentionally unchanged.
begin;
create or replace function public.pro_work_schedule_owner(p_actor uuid,p_work text) returns void language plpgsql volatile security invoker set search_path=public,pg_temp as $$
begin if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) or not exists(select 1 from public.pro_work where user_id=p_actor and id=p_work) then raise exception 'Forbidden' using errcode='42501';end if;end $$;
revoke all on function public.pro_work_schedule_owner(uuid,text) from public,anon,authenticated;
grant execute on function public.pro_work_schedule_owner(uuid,text) to service_role;
commit;
notify pgrst, 'reload schema';

-- ===== private-daily-logs-access-local.sql =====
-- LOCAL Pro only. Three allowlisted owner-only access substitutions.
-- Team current-generation and historical client publication rules unchanged.
begin;
create or replace function public.pro_daily_log_defaults_read(p_actor uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare d pro_daily_log_defaults;begin if not coalesce(pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;select * into d from pro_daily_log_defaults where owner_id=p_actor;if not found then return jsonb_build_object('revision',0,'summary','','sections',jsonb_build_object('weather',false,'plan',false,'tasks',false,'time',false));end if;return jsonb_build_object('revision',d.revision,'summary',d.summary,'sections',d.sections);end $$;
create or replace function public.pro_daily_logs_mutate(p_actor uuid,p_input jsonb) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text;aid uuid;lid uuid;target uuid;wid text;gid uuid;own uuid;rev integer;ctx jsonb;receipt pro_daily_log_actions;l pro_daily_logs;d pro_daily_log_defaults;g pro_team_grants;r pro_appointment_requests;keys text[];expected text[];is_owner boolean;before_json jsonb;after_json jsonb;answer jsonb;snapshot_json jsonb;weather_json jsonb;day date;task_ids uuid[];plan_ids uuid[];sections_json jsonb;ref jsonb;team_ids uuid[]:='{}';version_no integer;version_json jsonb;service_name text;
begin
 if not exists(select 1 from profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input) is distinct from 'object' or jsonb_typeof(p_input->'action') is distinct from 'string' or jsonb_typeof(p_input->'actionId') is distinct from 'string' or jsonb_typeof(p_input->'revision') is distinct from 'number' or not coalesce((p_input->>'revision')~'^[0-9]{1,10}$',false) or(p_input->>'revision')::numeric not between 0 and 2147483646 then raise exception 'Invalid identity' using errcode='22023';end if;
 act:=p_input->>'action';aid:=(p_input->>'actionId')::uuid;rev:=(p_input->>'revision')::integer;
 if act in('create','update') then expected:=array['action','actionId','date','grantId','logId','revision','sections','source','summary','title','weather','workId'];
 elsif act='duplicate' then expected:=array['action','actionId','grantId','logId','revision','targetLogId','workId'];
 elsif act in('archive','restore') then expected:=array['action','actionId','grantId','logId','revision','workId'];
 elsif act='publish' then expected:=array['action','actionId','client','grantId','logId','revision','team','workId'];
 elsif act='defaults_save' then expected:=array['action','actionId','revision','sections','summary'];else raise exception 'Unknown daily log action' using errcode='22023';end if;
 select array_agg(key order by key) into keys from jsonb_object_keys(p_input)key;if keys is distinct from expected then raise exception 'Unexpected daily log fields' using errcode='22023';end if;
 if act='defaults_save' then if not coalesce(pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;own:=p_actor;is_owner:=true;
 else
  if jsonb_typeof(p_input->'workId') is distinct from 'string' or jsonb_typeof(p_input->'grantId') not in('string','null') or jsonb_typeof(p_input->'logId') is distinct from 'string' then raise exception 'Invalid scope' using errcode='22023';end if;
  wid:=p_input->>'workId';gid:=(p_input->>'grantId')::uuid;lid:=(p_input->>'logId')::uuid;ctx:=pro_daily_log_context(p_actor,wid,gid,true);own:=(ctx->>'ownerId')::uuid;is_owner:=(ctx->>'isOwner')::boolean;
  if act='publish' and not is_owner then raise exception 'Forbidden' using errcode='42501';end if;
 end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-daily-log-action:'||p_actor::text||':'||aid::text,0));
 if act='defaults_save' then perform pg_advisory_xact_lock(hashtextextended('pro-daily-log-defaults:'||own::text,0));if not coalesce(pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 else
  -- Same owner/work advisory as Team role/revoke and task/plan writers. Team
  -- takes grant rows after this advisory. Appointment writes request before work.
  perform pg_advisory_xact_lock(hashtextextended('pro-work-tasks:'||own::text||':'||wid,0));
  if gid is not null then perform 1 from pro_team_grants where id=gid for share;end if;
  ctx:=pro_daily_log_context(p_actor,wid,gid,true);if (ctx->>'ownerId')::uuid<>own then raise exception 'Forbidden' using errcode='42501';end if;
 end if;
 select * into receipt from pro_daily_log_actions where actor_id=p_actor and action_id=aid;
 if found then
  if receipt.work_id is distinct from wid or receipt.owner_id<>own or receipt.grant_id is distinct from(gid) or receipt.source_invite_id is distinct from(ctx->>'sourceInviteId')::uuid then raise exception 'Forbidden' using errcode='42501';end if;
  if receipt.input is distinct from p_input then raise exception 'Action identity reused' using errcode='22023';end if;return receipt.result;
 end if;
 if act='defaults_save' then
  if jsonb_typeof(p_input->'summary') is distinct from 'string' or length(p_input->>'summary')>2000 or jsonb_typeof(p_input->'sections') is distinct from 'object' or not pro_daily_log_sections_valid(p_input->'sections') then raise exception 'Invalid defaults' using errcode='22023';end if;
  select * into d from pro_daily_log_defaults where owner_id=own for update;if coalesce(d.revision,0)<>rev then raise exception 'Defaults changed' using errcode='40001';end if;
  before_json:=pro_daily_log_defaults_read(p_actor);insert into pro_daily_log_defaults(owner_id,revision,summary,sections) values(own,rev+1,btrim(p_input->>'summary'),p_input->'sections') on conflict(owner_id) do update set revision=excluded.revision,summary=excluded.summary,sections=excluded.sections;
  answer:=jsonb_build_object('action',act,'defaults',pro_daily_log_defaults_read(p_actor));after_json:=answer->'defaults';
 else
  if act='publish' then
   if jsonb_typeof(p_input->'client') not in('null','object') or jsonb_typeof(p_input->'team') is distinct from 'array' or jsonb_array_length(p_input->'team')>100 or p_input->'client'='null'::jsonb and jsonb_array_length(p_input->'team')=0 then raise exception 'Choose a bounded audience' using errcode='22023';end if;
   if p_input->'client'<>'null'::jsonb then
    if(select array_agg(key order by key) from jsonb_object_keys(p_input->'client')key) is distinct from array['recipientId','requestId'] then raise exception 'Invalid client audience' using errcode='22023';end if;
    select * into r from pro_appointment_requests where id=(p_input->'client'->>'requestId')::uuid and owner_id=own and work_id=wid for share;if not found then raise exception 'Client changed' using errcode='40001';end if;
   end if;
   for ref in select value from jsonb_array_elements(p_input->'team') order by value->>'grantId' loop
    if jsonb_typeof(ref) is distinct from 'object' or(select array_agg(key order by key) from jsonb_object_keys(ref)key) is distinct from array['grantId','sourceInviteId'] or jsonb_typeof(ref->'grantId') is distinct from 'string' or jsonb_typeof(ref->'sourceInviteId') is distinct from 'string' then raise exception 'Invalid team audience' using errcode='22023';end if;
    if(ref->>'grantId')::uuid=any(team_ids) then raise exception 'Duplicate team audience' using errcode='22023';end if;team_ids:=array_append(team_ids,(ref->>'grantId')::uuid);
    select * into g from pro_team_grants where id=(ref->>'grantId')::uuid and owner_id=own and work_id=wid for share;
    if not found or not g.active or g.member_user_id=own or g.source_invite_id<>(ref->>'sourceInviteId')::uuid or not exists(select 1 from profiles where id=g.member_user_id and not coalesce(is_disabled,false)) then raise exception 'Team audience changed' using errcode='40001';end if;
   end loop;
  end if;
  -- Do not take a work row lock: existing appointment work guards acquire the
  -- request row while holding work UPDATE. Sources are one coherent MVCC read,
  -- captured with fingerprint CAS; cost commits afterward cannot rewrite it.
  perform 1 from pro_work where user_id=own and id=wid;if not found then raise exception 'Forbidden' using errcode='42501';end if;
  select * into l from pro_daily_logs where owner_id=own and work_id=wid and id=lid for update;
  if act='create' then if found or rev<>0 then raise exception 'Daily log identity changed' using errcode='40001';end if;
  else if not found or not pro_daily_log_visible(p_actor,ctx,l) then raise exception 'Forbidden' using errcode='42501';end if;if l.revision<>rev then raise exception 'Daily log changed' using errcode='40001';end if;before_json:=pro_daily_log_json(l);end if;
  if act in('create','duplicate') and(select count(*) from pro_daily_logs where owner_id=own and work_id=wid)>=500 then raise exception 'Daily log capacity exceeded' using errcode='40001';end if;
  if act in('create','update') then
   if act='update' and l.archived then raise exception 'Restore before editing' using errcode='40001';end if;
   if jsonb_typeof(p_input->'date') is distinct from 'string' or not coalesce((p_input->>'date')~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$',false) or jsonb_typeof(p_input->'title') is distinct from 'string' or length(btrim(p_input->>'title')) not between 1 and 160 or jsonb_typeof(p_input->'summary') is distinct from 'string' or length(p_input->>'summary')>2000 or jsonb_typeof(p_input->'sections') is distinct from 'object' or not pro_daily_log_sections_valid(p_input->'sections') or jsonb_typeof(p_input->'weather') not in('object','null') or jsonb_typeof(p_input->'source') is distinct from 'object' then raise exception 'Invalid daily log content' using errcode='22023';end if;
   day:=(p_input->>'date')::date;if day not between date'1900-01-01' and date'2100-12-31' then raise exception 'Invalid daily log date' using errcode='22023';end if;sections_json:=p_input->'sections';weather_json:=nullif(p_input->'weather','null'::jsonb);
   if not(sections_json->>'weather')::boolean and weather_json is not null then raise exception 'Weather section disabled' using errcode='22023';end if;
   if weather_json is not null then
    if(select array_agg(key order by key) from jsonb_object_keys(weather_json)key) is distinct from array['condition','note','temperatureC'] or weather_json->>'condition' not in('clear','cloudy','rain','other') or jsonb_typeof(weather_json->'condition') is distinct from 'string' or jsonb_typeof(weather_json->'note') is distinct from 'string' or length(weather_json->>'note')>300 or jsonb_typeof(weather_json->'temperatureC') not in('number','null') or(weather_json->>'temperatureC')::numeric not between -20 and 60 then raise exception 'Invalid manual weather' using errcode='22023';end if;
   end if;
   if p_input->'source'->>'mode'='keep' then
    if act='create' or p_input->'source'<>jsonb_build_object('mode','keep') or l.log_date<>day or l.sections<>sections_json then raise exception 'Refresh sources after changing date or sections' using errcode='22023';end if;snapshot_json:=l.snapshot;
   elsif p_input->'source'->>'mode'='capture' then
    if(select array_agg(key order by key) from jsonb_object_keys(p_input->'source')key) is distinct from array['fingerprint','mode','planTaskIds','taskIds'] or jsonb_typeof(p_input->'source'->'taskIds') is distinct from 'array' or jsonb_typeof(p_input->'source'->'planTaskIds') is distinct from 'array' or not coalesce((p_input->'source'->>'fingerprint')~'^[a-f0-9]{32}$',false) then raise exception 'Invalid source capture' using errcode='22023';end if;
    select coalesce(array_agg(value::uuid),'{}') into task_ids from jsonb_array_elements_text(p_input->'source'->'taskIds');select coalesce(array_agg(value::uuid),'{}') into plan_ids from jsonb_array_elements_text(p_input->'source'->'planTaskIds');
    if not(sections_json->>'tasks')::boolean and cardinality(task_ids)>0 or not(sections_json->>'plan')::boolean and cardinality(plan_ids)>0 then raise exception 'Disabled source section' using errcode='22023';end if;
    snapshot_json:=pro_daily_log_snapshot(p_actor,wid,gid,p_input->>'date',task_ids,plan_ids,(sections_json->>'time')::boolean);if snapshot_json->>'fingerprint'<>p_input->'source'->>'fingerprint' then raise exception 'Sources changed; refresh before saving' using errcode='40001';end if;
   else raise exception 'Invalid source mode' using errcode='22023';end if;
   if act='create' then
    insert into pro_daily_logs(owner_id,work_id,id,log_date,title,summary,sections,weather,snapshot,revision,created_by,created_by_name,created_grant_id,source_invite_id) values(own,wid,lid,day,btrim(p_input->>'title'),btrim(p_input->>'summary'),sections_json,weather_json,snapshot_json,1,p_actor,pro_team_name(p_actor),(ctx->>'grantId')::uuid,(ctx->>'sourceInviteId')::uuid) returning * into l;
   else update pro_daily_logs set log_date=day,title=btrim(p_input->>'title'),summary=btrim(p_input->>'summary'),sections=sections_json,weather=weather_json,snapshot=snapshot_json,revision=revision+1,updated_at=now() where owner_id=own and work_id=wid and id=lid returning * into l;end if;
  elsif act='duplicate' then
   if jsonb_typeof(p_input->'targetLogId') is distinct from 'string' then raise exception 'Invalid duplicate identity' using errcode='22023';end if;target:=(p_input->>'targetLogId')::uuid;
   if exists(select 1 from pro_daily_logs where owner_id=own and work_id=wid and id=target) then raise exception 'Duplicate identity used' using errcode='40001';end if;
   insert into pro_daily_logs(owner_id,work_id,id,log_date,title,summary,sections,weather,snapshot,revision,created_by,created_by_name,created_grant_id,source_invite_id) values(own,wid,target,l.log_date,l.title,l.summary,l.sections,l.weather,l.snapshot,1,p_actor,pro_team_name(p_actor),(ctx->>'grantId')::uuid,(ctx->>'sourceInviteId')::uuid) returning * into l;
  elsif act in('archive','restore') then
   if l.archived=(act='archive') then raise exception 'Daily log status changed' using errcode='40001';end if;update pro_daily_logs set archived=(act='archive'),revision=revision+1,updated_at=now() where owner_id=own and work_id=wid and id=lid returning * into l;
  else
   if l.archived then raise exception 'Restore before publishing' using errcode='40001';end if;
   if p_input->'client'<>'null'::jsonb and(r.client_user_id is distinct from(p_input->'client'->>'recipientId')::uuid or r.status not in('confirmed','completed') or not exists(select 1 from profiles where id=r.client_user_id and not coalesce(is_disabled,false)) or exists(select 1 from pro_work where user_id=own and id=wid and coalesce(cancelled,false))) then raise exception 'Client audience changed' using errcode='40001';end if;
   if exists(select 1 from pro_team_grants target_grant where target_grant.id=any(team_ids) and(not target_grant.active or not exists(select 1 from profiles p where p.id=target_grant.member_user_id and not coalesce(p.is_disabled,false)))) then raise exception 'Team audience changed' using errcode='40001';end if;
   update pro_daily_logs set revision=revision+1,published_revision=revision+1,updated_at=now() where owner_id=own and work_id=wid and id=lid returning * into l;
   select coalesce(max(version),0)+1 into version_no from pro_daily_log_versions where owner_id=own and work_id=wid and log_id=lid;select service into service_name from pro_work where user_id=own and id=wid;
   version_json:=jsonb_build_object('id',lid,'version',version_no,'date',to_char(l.log_date,'YYYY-MM-DD'),'title',l.title,'summary',l.summary,'sections',l.sections,'weather',l.weather,'snapshot',l.snapshot,'service',service_name,'authorName',l.created_by_name,'publishedAt',now());
   insert into pro_daily_log_versions values(own,wid,lid,version_no,l.revision,version_json);
   if p_input->'client'<>'null'::jsonb then insert into pro_daily_log_audiences(owner_id,work_id,log_id,version,kind,recipient_id,request_id) values(own,wid,lid,version_no,'client',r.client_user_id,r.id);end if;
   insert into pro_daily_log_audiences(owner_id,work_id,log_id,version,kind,recipient_id,grant_id,source_invite_id) select own,wid,lid,version_no,'team',target_grant.member_user_id,target_grant.id,target_grant.source_invite_id from pro_team_grants target_grant where target_grant.id=any(team_ids);
  end if;
  ctx:=pro_daily_log_context(p_actor,wid,gid,true);after_json:=pro_daily_log_json(l);answer:=jsonb_build_object('action',act,'log',after_json);if act='publish' then answer:=answer||jsonb_build_object('version',version_json);end if;
  insert into pro_daily_log_history(owner_id,work_id,log_id,action_id,actor_id,actor_name,action,before_log,after_log) values(own,wid,l.id,aid,p_actor,pro_team_name(p_actor),act,before_json,after_json);
 end if;
 if not coalesce(case when is_owner then pro_private_work_tools_enabled(own) else pro_appointment_enabled(own) end,false) or not exists(select 1 from profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 insert into pro_daily_log_actions(actor_id,action_id,owner_id,work_id,grant_id,source_invite_id,input,result,before_state,after_state) values(p_actor,aid,own,wid,gid,case when ctx is null then null else(ctx->>'sourceInviteId')::uuid end,p_input,answer,before_json,after_json);return answer;
end $$;
create or replace function public.pro_daily_log_action_read(p_actor uuid,p_action uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare r pro_daily_log_actions;ctx jsonb;begin
 if not exists(select 1 from profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into r from pro_daily_log_actions where actor_id=p_actor and action_id=p_action;if not found then return jsonb_build_object('receipt',null);end if;
 if r.work_id is null then if r.owner_id<>p_actor or not coalesce(pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 else ctx:=pro_daily_log_context(p_actor,r.work_id,r.grant_id,true);if(ctx->>'ownerId')::uuid<>r.owner_id or(ctx->>'sourceInviteId')::uuid is distinct from r.source_invite_id then raise exception 'Forbidden' using errcode='42501';end if;end if;
 return jsonb_build_object('receipt',jsonb_build_object('input',r.input,'result',r.result));
end $$;
revoke all on function public.pro_daily_log_defaults_read(uuid) from public,anon,authenticated;
grant execute on function public.pro_daily_log_defaults_read(uuid) to service_role;
revoke all on function public.pro_daily_logs_mutate(uuid,jsonb) from public,anon,authenticated;
grant execute on function public.pro_daily_logs_mutate(uuid,jsonb) to service_role;
revoke all on function public.pro_daily_log_action_read(uuid,uuid) from public,anon,authenticated;
grant execute on function public.pro_daily_log_action_read(uuid,uuid) to service_role;
commit;
notify pgrst, 'reload schema';

-- ===== private-daily-file-recovery-access-local.sql =====
-- LOCAL Pro only: two owner receipt readers, no writer or audience changes.
begin;
create or replace function public.pro_daily_file_reconcile_read(p_actor uuid,p_action uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare a pro_daily_log_file_reconcile_actions;begin
 if not coalesce(pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;select * into a from pro_daily_log_file_reconcile_actions where owner_id=p_actor and action_id=p_action;if not found then return jsonb_build_object('attempt',null);end if;perform pro_daily_file_reconcile_owner(p_actor,a.work_id,a.log_id);return jsonb_build_object('attempt',pro_daily_file_reconcile_json(a));end $$;
create or replace function public.pro_daily_log_duplicate_retire_read(p_actor uuid,p_action uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare r pro_daily_log_duplicate_retirements;begin
 if not coalesce(pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into r from pro_daily_log_duplicate_retirements where owner_id=p_actor and action_id=p_action;if not found then return jsonb_build_object('retirement',null);end if;perform pro_work_schedule_owner(p_actor,r.work_id);return jsonb_build_object('retirement',r.result);end $$;
revoke all on function public.pro_daily_file_reconcile_read(uuid,uuid) from public,anon,authenticated;
grant execute on function public.pro_daily_file_reconcile_read(uuid,uuid) to service_role;
revoke all on function public.pro_daily_log_duplicate_retire_read(uuid,uuid) from public,anon,authenticated;
grant execute on function public.pro_daily_log_duplicate_retire_read(uuid,uuid) to service_role;
commit;
notify pgrst, 'reload schema';

-- ===== private-estimates-local.sql =====
-- LOCAL private draft estimates only: no public quotation, acceptance or financial posting.
begin;
create table if not exists pro_private_estimates(owner_id uuid not null references profiles(id) on delete cascade,id uuid not null,client_id text not null,client_snapshot jsonb not null,source jsonb,issuer jsonb not null,title text not null,notes text not null,currency text not null check(currency in('CRC','USD')),valid_until date,subtotal_cents bigint not null check(subtotal_cents between 0 and 9000000000000),discount_cents bigint not null check(discount_cents between 0 and 9000000000000),tax_cents bigint not null check(tax_cents between 0 and 9000000000000),total_cents bigint not null check(total_cents between 0 and 9000000000000),revision integer not null check(revision>0),archived boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),primary key(owner_id,id),foreign key(owner_id,client_id) references pro_clients(user_id,id));
create table if not exists pro_private_estimate_items(owner_id uuid not null,estimate_id uuid not null,id uuid not null,position integer not null,content jsonb not null,primary key(owner_id,estimate_id,id),unique(owner_id,estimate_id,position),foreign key(owner_id,estimate_id) references pro_private_estimates(owner_id,id) on delete cascade);
create table if not exists pro_private_estimate_actions(actor_id uuid not null references profiles(id) on delete cascade,action_id uuid not null,input jsonb not null,result jsonb not null,at timestamptz not null default now(),primary key(actor_id,action_id));
create table if not exists pro_private_estimate_history(owner_id uuid not null,estimate_id uuid not null,action_id uuid not null,action text not null,before_estimate jsonb,after_estimate jsonb not null,at timestamptz not null default now(),primary key(owner_id,action_id),foreign key(owner_id,estimate_id) references pro_private_estimates(owner_id,id) on delete cascade);
create index if not exists pro_private_estimate_page on pro_private_estimates(owner_id,archived,created_at desc,id desc);
create or replace function pro_private_estimate_totals(p_lines jsonb) returns jsonb language plpgsql immutable security invoker set search_path=public,pg_temp as $$declare l jsonb;b numeric;d numeric;n numeric;t numeric;s numeric:=0;ds numeric:=0;ts numeric:=0;tot numeric:=0;begin
 if jsonb_typeof(p_lines) is distinct from 'array' or jsonb_array_length(p_lines) not between 1 and 100 then raise exception 'Invalid lines' using errcode='22023';end if;
 if (select count(distinct value->>'id') from jsonb_array_elements(p_lines))<>jsonb_array_length(p_lines) then raise exception 'Duplicate line' using errcode='22023';end if;
 for l in select value from jsonb_array_elements(p_lines) loop
 if jsonb_typeof(l) is distinct from 'object' or (select array_agg(key order by key) from jsonb_object_keys(l)key) is distinct from array['catalogProductId','description','discountBps','id','qtyMilli','taxBps','unit','unitPriceCents'] or l->>'id' is null or length(btrim(l->>'description')) not between 1 and 2000 or length(l->>'unit')>30 then raise exception 'Invalid line fields' using errcode='22023';end if;
 perform (l->>'id')::uuid;if jsonb_typeof(l->'id') is distinct from 'string' or jsonb_typeof(l->'description') is distinct from 'string' or jsonb_typeof(l->'unit') is distinct from 'string' or jsonb_typeof(l->'catalogProductId') not in('null','string') or jsonb_typeof(l->'qtyMilli') is distinct from 'number' or jsonb_typeof(l->'unitPriceCents') is distinct from 'number' or jsonb_typeof(l->'discountBps') is distinct from 'number' or jsonb_typeof(l->'taxBps') is distinct from 'number' then raise exception 'Invalid line types' using errcode='22023';end if;
 if not coalesce(l->>'qtyMilli'~'^[0-9]+$',false) or not coalesce(l->>'unitPriceCents'~'^[0-9]+$',false) or not coalesce(l->>'discountBps'~'^[0-9]+$',false) or not coalesce(l->>'taxBps'~'^[0-9]+$',false) or (l->>'qtyMilli')::numeric not between 1 and 100000000 or (l->>'unitPriceCents')::numeric not between 0 and 10000000000 or (l->>'discountBps')::numeric not between 0 and 10000 or (l->>'taxBps')::numeric not between 0 and 10000 then raise exception 'Invalid line money' using errcode='22023';end if;
 b:=round((l->>'qtyMilli')::numeric*(l->>'unitPriceCents')::numeric/1000);d:=round(b*(l->>'discountBps')::numeric/10000);n:=b-d;t:=round(n*(l->>'taxBps')::numeric/10000);s:=s+b;ds:=ds+d;ts:=ts+t;tot:=tot+n+t;
 end loop;
 if greatest(s,ds,ts,tot)>9000000000000 then raise exception 'Estimate overflow' using errcode='22023';end if;return jsonb_build_object('subtotalCents',s,'discountCents',ds,'taxCents',ts,'totalCents',tot);end $$;
create or replace function pro_private_estimate_json(p_doc pro_private_estimates) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
 with lines as(select coalesce(jsonb_agg(content order by position),'[]'::jsonb) value from pro_private_estimate_items where owner_id=p_doc.owner_id and estimate_id=p_doc.id)
 select jsonb_build_object('kind','private_estimate','id',p_doc.id,'ownerId',p_doc.owner_id,'revision',p_doc.revision,'status',case when p_doc.archived then 'archived' else 'draft' end,'clientId',p_doc.client_id,'client',p_doc.client_snapshot,'clientFingerprint',md5(p_doc.client_snapshot::text),'source',p_doc.source,'issuer',p_doc.issuer,'title',p_doc.title,'notes',p_doc.notes,'currency',p_doc.currency,'validUntil',p_doc.valid_until,'lines',lines.value,'createdAt',p_doc.created_at,'updatedAt',p_doc.updated_at,'subtotalCents',p_doc.subtotal_cents,'discountCents',p_doc.discount_cents,'taxCents',p_doc.tax_cents,'totalCents',p_doc.total_cents) from lines $$;
create or replace function pro_private_estimate_context(p_actor uuid,p_client text default null,p_kind text default null,p_id text default null) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare c pro_clients;l pro_lead_center_records;w pro_work;src jsonb;title_text text:='';config jsonb;begin
 if not coalesce(pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_kind='manual' then select * into l from pro_lead_center_records where owner_id=p_actor and kind='manual' and id=p_id::uuid;if not found or l.archived then raise exception 'Opportunity changed' using errcode='40001';end if;p_client:=l.client_id;title_text:=l.title;src:=jsonb_build_object('kind','manual','id',l.id,'revision',l.revision);
 elsif p_kind='work' then select * into w from pro_work where user_id=p_actor and id=p_id;if not found or coalesce(w.cancelled,false) then raise exception 'Work changed' using errcode='40001';end if;p_client:=w."clientId";title_text:=w.service;src:=jsonb_build_object('kind','work','id',w.id,'fingerprint',md5(to_jsonb(w)::text));
 elsif p_kind is not null or p_id is not null then raise exception 'Invalid source' using errcode='22023';end if;
 select * into c from pro_clients where user_id=p_actor and id=p_client;if not found or c.archived then raise exception 'Choose an active customer' using errcode='40001';end if;config:=pro_invoice_issuer_read(p_actor);
 return jsonb_build_object('client',jsonb_build_object('id',c.id,'name',c.name,'email',c.email,'phone',c.phone,'identification',c.identification,'address',c.address,'tradeName',c."tradeName"),'clientFingerprint',md5((jsonb_build_object('id',c.id,'name',c.name,'email',c.email,'phone',c.phone,'identification',c.identification,'address',c.address,'tradeName',c."tradeName"))::text),'source',src,'issuer',config->'issuer','issuerRevision',config->'revision','title',title_text,'currency','CRC');end $$;
create or replace function pro_private_estimate_mutate(p_actor uuid,p_input jsonb) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$declare aid uuid;eid uuid;target uuid;act text;rev integer;r pro_private_estimate_actions;d pro_private_estimates;before_json jsonb;answer jsonb;ctx jsonb;client_json jsonb;src jsonb;line jsonb;pos integer:=0;old_lines jsonb;keys text[];totals jsonb;begin
 if not coalesce(pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input) is distinct from 'object' then raise exception 'Invalid operation' using errcode='22023';end if;
 act:=p_input->>'action';aid:=(p_input->>'actionId')::uuid;eid:=(p_input->>'estimateId')::uuid;
 if aid is null or eid is null or not coalesce(p_input->>'revision'~'^[0-9]+$',false) or (p_input->>'revision')::numeric not between 0 and 2147483646 then raise exception 'Invalid operation identity' using errcode='22023';end if;rev:=(p_input->>'revision')::integer;
 select array_agg(key order by key) into keys from jsonb_object_keys(p_input)key;
 if act='save' then if keys is distinct from array['action','actionId','clientFingerprint','clientId','currency','estimateId','issuer','lines','notes','refreshClient','revision','source','title','validUntil'] then raise exception 'Invalid save fields' using errcode='22023';end if;
 elsif act='duplicate' then if keys is distinct from array['action','actionId','estimateId','revision','targetEstimateId'] then raise exception 'Invalid duplicate fields' using errcode='22023';end if;
 elsif act in('archive','restore') then if keys is distinct from array['action','actionId','estimateId','revision'] then raise exception 'Invalid archive fields' using errcode='22023';end if;else raise exception 'Invalid action' using errcode='22023';end if;
 -- Same owner mutex as normalized clients/work. No public issuer row required.
 perform pg_advisory_xact_lock(hashtextextended(p_actor::text,0));perform pg_advisory_xact_lock(hashtextextended('pro-private-estimate-action:'||p_actor::text||':'||aid::text,0));
 if not coalesce(pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into r from pro_private_estimate_actions where actor_id=p_actor and action_id=aid;if found then if r.input is distinct from p_input then raise exception 'Action identity reused' using errcode='22023';end if;return r.result;end if;
 select * into d from pro_private_estimates where owner_id=p_actor and id=eid for update;
 if not coalesce(pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if coalesce(d.revision,0)<>rev or d.id is null and act<>'save' then raise exception 'Estimate changed' using errcode='40001';end if;
 if d.id is not null then before_json:=pro_private_estimate_json(d);old_lines:=before_json->'lines';end if;
 if act='save' then
  if d.archived then raise exception 'Restore before editing' using errcode='40001';end if;
  totals:=pro_private_estimate_totals(p_input->'lines');
  if jsonb_typeof(p_input->'title') is distinct from 'string' or length(btrim(p_input->>'title')) not between 1 and 160 or jsonb_typeof(p_input->'notes') is distinct from 'string' or length(p_input->>'notes')>2000 or jsonb_typeof(p_input->'currency') is distinct from 'string' or p_input->>'currency' not in('CRC','USD') or jsonb_typeof(p_input->'validUntil') not in('null','string') or jsonb_typeof(p_input->'refreshClient') is distinct from 'boolean' or jsonb_typeof(p_input->'issuer') is distinct from 'object' or length(btrim(p_input->'issuer'->>'issuerName')) not between 1 and 160 then raise exception 'Invalid estimate content' using errcode='22023';end if;
  if (select array_agg(key order by key) from jsonb_object_keys(p_input->'issuer')key) is distinct from array['issuerActivity','issuerAddress','issuerEmail','issuerId','issuerIdType','issuerName','issuerPhone'] or exists(select 1 from jsonb_each(p_input->'issuer')e where jsonb_typeof(e.value)<>'string') or p_input->'issuer'->>'issuerIdType' not in('','individual','company','dimex','nite','foreign') or length(p_input->'issuer'->>'issuerName')>160 or length(p_input->'issuer'->>'issuerId')>40 or length(p_input->'issuer'->>'issuerEmail')>254 or length(p_input->'issuer'->>'issuerPhone')>30 or length(p_input->'issuer'->>'issuerAddress')>500 or length(p_input->'issuer'->>'issuerActivity')>12 then raise exception 'Invalid issuer snapshot' using errcode='22023';end if;
  if jsonb_typeof(p_input->'source') not in('null','object') or p_input->'source'<>'null'::jsonb and ((p_input->'source'->>'kind'='manual' and(select array_agg(key order by key) from jsonb_object_keys(p_input->'source')key) is distinct from array['id','kind','revision']) or(p_input->'source'->>'kind'='work' and(select array_agg(key order by key) from jsonb_object_keys(p_input->'source')key) is distinct from array['fingerprint','id','kind']) or coalesce(p_input->'source'->>'kind','') not in('manual','work')) then raise exception 'Invalid source fields' using errcode='22023';end if;
  if jsonb_typeof(p_input->'clientId') is distinct from 'string' or length(p_input->>'clientId') not between 1 and 160 or not coalesce(p_input->>'clientFingerprint'~'^[a-f0-9]{32}$',false) then raise exception 'Invalid client snapshot' using errcode='22023';end if;
  if d.id is null then
   src:=p_input->'source';
   if src->>'kind'='manual' then perform 1 from pro_lead_center_records where owner_id=p_actor and kind='manual' and id=(src->>'id')::uuid for share;
   elsif src->>'kind'='work' then perform 1 from pro_work where user_id=p_actor and id=src->>'id' for share;end if;
   perform 1 from pro_clients where user_id=p_actor and id=p_input->>'clientId' for share;
   ctx:=pro_private_estimate_context(p_actor,p_input->>'clientId',src->>'kind',src->>'id');if ctx->'source' is distinct from src or ctx->'client'->>'id' is distinct from p_input->>'clientId' then raise exception 'Source changed' using errcode='40001';end if;client_json:=ctx->'client';
  else
   if d.source is not null and d.source<>'null'::jsonb and p_input->>'clientId'<>d.client_id then raise exception 'Source-bound customer is immutable' using errcode='22023';end if;
   if p_input->'source' is distinct from coalesce(d.source,'null'::jsonb) then raise exception 'Origin is immutable' using errcode='22023';end if;src:=d.source;
   if p_input->>'clientId'=d.client_id and not(p_input->>'refreshClient')::boolean then client_json:=d.client_snapshot;
   else perform 1 from pro_clients where user_id=p_actor and id=p_input->>'clientId' for share;ctx:=pro_private_estimate_context(p_actor,p_input->>'clientId');client_json:=ctx->'client';end if;
  end if;
  if md5(client_json::text) is distinct from p_input->>'clientFingerprint' then raise exception 'Customer snapshot changed' using errcode='40001';end if;
  if p_input->>'validUntil' is not null and ((p_input->>'validUntil')::date not between date'1900-01-01' and date'2100-12-31' or to_char((p_input->>'validUntil')::date,'YYYY-MM-DD')<>p_input->>'validUntil') then raise exception 'Invalid date' using errcode='22023';end if;
  for line in select value from jsonb_array_elements(p_input->'lines') loop
   if line->>'catalogProductId' is not null and not exists(select 1 from pro_products where user_id=p_actor and id=line->>'catalogProductId' and(not archived or exists(select 1 from jsonb_array_elements(coalesce(old_lines,'[]'::jsonb)) old where old->>'id'=line->>'id' and old->>'catalogProductId'=line->>'catalogProductId'))) then raise exception 'Product changed' using errcode='40001';end if;
  end loop;
  insert into pro_private_estimates(owner_id,id,client_id,client_snapshot,source,issuer,title,notes,currency,valid_until,subtotal_cents,discount_cents,tax_cents,total_cents,revision) values(p_actor,eid,p_input->>'clientId',client_json,src,p_input->'issuer',btrim(p_input->>'title'),p_input->>'notes',p_input->>'currency',(p_input->>'validUntil')::date,(totals->>'subtotalCents')::bigint,(totals->>'discountCents')::bigint,(totals->>'taxCents')::bigint,(totals->>'totalCents')::bigint,rev+1) on conflict(owner_id,id) do update set client_id=excluded.client_id,client_snapshot=excluded.client_snapshot,issuer=excluded.issuer,title=excluded.title,notes=excluded.notes,currency=excluded.currency,valid_until=excluded.valid_until,subtotal_cents=excluded.subtotal_cents,discount_cents=excluded.discount_cents,tax_cents=excluded.tax_cents,total_cents=excluded.total_cents,revision=excluded.revision,updated_at=now() returning * into d;
  delete from pro_private_estimate_items where owner_id=p_actor and estimate_id=eid;for line in select value from jsonb_array_elements(p_input->'lines') loop pos:=pos+1;insert into pro_private_estimate_items values(p_actor,eid,(line->>'id')::uuid,pos,line);end loop;
 elsif act='duplicate' then
  target:=(p_input->>'targetEstimateId')::uuid;if target is null or exists(select 1 from pro_private_estimates where owner_id=p_actor and id=target) then raise exception 'Duplicate target exists' using errcode='40001';end if;
  insert into pro_private_estimates(owner_id,id,client_id,client_snapshot,source,issuer,title,notes,currency,valid_until,subtotal_cents,discount_cents,tax_cents,total_cents,revision) values(p_actor,target,d.client_id,d.client_snapshot,d.source,d.issuer,d.title,d.notes,d.currency,d.valid_until,d.subtotal_cents,d.discount_cents,d.tax_cents,d.total_cents,1);
  insert into pro_private_estimate_items select owner_id,target,id,position,content from pro_private_estimate_items where owner_id=p_actor and estimate_id=eid;select * into d from pro_private_estimates where owner_id=p_actor and id=target;
 else
  if d.archived=(act='archive') then raise exception 'Estimate status changed' using errcode='40001';end if;update pro_private_estimates set archived=(act='archive'),revision=revision+1,updated_at=now() where owner_id=p_actor and id=eid returning * into d;
 end if;
 answer:=jsonb_build_object('action',act,'estimate',pro_private_estimate_json(d));
 insert into pro_private_estimate_history(owner_id,estimate_id,action_id,action,before_estimate,after_estimate)values(p_actor,d.id,aid,act,before_json,answer->'estimate');insert into pro_private_estimate_actions values(p_actor,aid,p_input,answer,now());
 if not coalesce(pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;return answer;end $$;
create or replace function pro_private_estimate_action_read(p_actor uuid,p_action uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare r pro_private_estimate_actions;begin if not coalesce(pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;select * into r from pro_private_estimate_actions where actor_id=p_actor and action_id=p_action;if not found then return jsonb_build_object('receipt',null);end if;return jsonb_build_object('receipt',jsonb_build_object('input',r.input,'result',r.result));end $$;
create or replace function pro_private_estimate_read(p_actor uuid,p_estimate uuid default null,p_status text default 'draft',p_query text default '',p_client text default null,p_currency text default null,p_after uuid default null,p_kind text default null,p_source text default null) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare d pro_private_estimates;items jsonb;cursor_time timestamptz;cursor_revision integer;next_id uuid;begin
 if not coalesce(pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if (p_kind is null)<>(p_source is null) or p_kind is not null and(p_kind not in('manual','work') or length(p_source) not between 1 and 160) then raise exception 'Invalid origin filter' using errcode='22023';end if;
 if p_estimate is not null then select * into d from pro_private_estimates where owner_id=p_actor and id=p_estimate;if not found then return null;end if;
 if p_after is not null then select (after_estimate->>'revision')::integer into cursor_revision from pro_private_estimate_history where owner_id=p_actor and estimate_id=p_estimate and action_id=p_after;if not found then raise exception 'History cursor changed' using errcode='40001';end if;end if;
 select coalesce(jsonb_agg(jsonb_build_object('actionId',h.action_id,'action',h.action,'at',h.at,'before',h.before_estimate,'after',h.after_estimate)order by(h.after_estimate->>'revision')::integer desc),'[]'::jsonb) into items from(select * from pro_private_estimate_history where owner_id=p_actor and estimate_id=p_estimate and(p_after is null or(after_estimate->>'revision')::integer<cursor_revision)order by(after_estimate->>'revision')::integer desc limit 21)h;
 if jsonb_array_length(items)>20 then next_id:=(items->19->>'actionId')::uuid;items:=items-20;end if;return jsonb_build_object('estimate',pro_private_estimate_json(d),'history',items,'nextCursor',next_id);end if;
 if p_status not in('draft','archived','all') or length(coalesce(p_query,''))>100 or p_currency is not null and p_currency not in('CRC','USD') then raise exception 'Invalid query' using errcode='22023';end if;
 if p_after is not null then select created_at into cursor_time from pro_private_estimates where owner_id=p_actor and id=p_after and(p_status='all' or archived=(p_status='archived')) and(p_client is null or client_id=p_client) and(p_currency is null or currency=p_currency) and(p_kind is null or source->>'kind'=p_kind and source->>'id'=p_source) and(position(lower(p_query) in lower(title||' '||(client_snapshot->>'name')))>0);if not found then raise exception 'Cursor changed' using errcode='40001';end if;end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'ownerId',x.owner_id,'revision',x.revision,'status',case when x.archived then 'archived' else 'draft' end,'clientId',x.client_id,'clientName',x.client_snapshot->>'name','source',x.source,'title',x.title,'currency',x.currency,'validUntil',x.valid_until,'subtotalCents',x.subtotal_cents,'discountCents',x.discount_cents,'taxCents',x.tax_cents,'totalCents',x.total_cents,'createdAt',x.created_at,'updatedAt',x.updated_at)order by x.created_at desc,x.id desc),'[]'::jsonb) into items from(select * from pro_private_estimates where owner_id=p_actor and(p_status='all' or archived=(p_status='archived')) and(p_client is null or client_id=p_client) and(p_currency is null or currency=p_currency) and(p_kind is null or source->>'kind'=p_kind and source->>'id'=p_source) and(position(lower(p_query) in lower(title||' '||(client_snapshot->>'name')))>0) and(p_after is null or(created_at,id)<(cursor_time,p_after))order by created_at desc,id desc limit 21)x;
 if jsonb_array_length(items)>20 then next_id:=(items->19->>'id')::uuid;items:=items-20;end if;return jsonb_build_object('items',items,'nextCursor',next_id);end $$;
create or replace function pro_private_estimate_sales_page(p_actor uuid,p_status text default 'all',p_query text default '',p_client text default null,p_after jsonb default null) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare items jsonb;cursor jsonb;anchor_valid boolean;begin
 if not coalesce(pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_status not in('all','draft','sent','accepted','declined','withdrawn','archived') or length(p_query)>100 or p_after is not null and(jsonb_typeof(p_after)<>'object' or(select array_agg(key order by key) from jsonb_object_keys(p_after)key) is distinct from array['at','key'] or jsonb_typeof(p_after->'at')<>'string' or jsonb_typeof(p_after->'key')<>'string') then raise exception 'Invalid sales query' using errcode='22023';end if;
 with rows as(
 select 'private_estimate' kind,d.id::text id,'private_estimate:'||d.id::text key,d.title,d.client_snapshot->>'name' client,d.client_id,case when d.archived then 'archived' else 'draft' end status,d.currency,d.total_cents::numeric total_cents,to_char(d.created_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"') at from pro_private_estimates d where d.owner_id=p_actor and(not d.archived or p_status='archived')
 union all select 'standard',q.id::text,'standard:'||q.id::text,coalesce(q.title,''),coalesce(q.client_name,''),l."clientId",q.status,'CRC',q.total::numeric*100,to_char(q.created_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"') from quotes q left join pro_quote_links l on l.user_id=p_actor and l."quoteId"=q.id::text where q.deleted_at is null and(q.client_id=p_actor or exists(select 1 from professionals p where p.id=q.professional_id and p.profile_id=p_actor))
 union all select 'legacy',q.id,'legacy:'||q.id,q.title,coalesce(c.name,''),q."clientId",q.status,'CRC',(select coalesce(sum(net+floor(net*l.tax::double precision/100+0.5)),0) from pro_legacy_quote_lines l cross join lateral(select floor(l.quantity::double precision*l.price::double precision*100+0.5) net)n where l.user_id=q.user_id and l.quote_id=q.id),'' from pro_legacy_quotes q left join pro_clients c on c.user_id=q.user_id and c.id=q."clientId" where q.user_id=p_actor
 ),filtered as(select * from rows where(p_status='all' or status=p_status) and(p_client is null or client_id=p_client) and position(lower(p_query) in lower(title||' '||client))>0),page as(select * from filtered where p_after is null or at<p_after->>'at' or at=p_after->>'at' and key>p_after->>'key' order by at desc,key asc limit 21)
 select coalesce(jsonb_agg(jsonb_build_object('kind',kind,'id',id,'key',key,'title',title,'client',client,'clientId',client_id,'status',status,'currency',currency,'totalCents',total_cents,'at',at)order by at desc,key asc),'[]'::jsonb),(p_after is null or exists(select 1 from filtered where at=p_after->>'at' and key=p_after->>'key')) into items,anchor_valid from page;
 if not anchor_valid then raise exception 'Sales cursor changed' using errcode='40001';end if;
 if jsonb_array_length(items)>20 then cursor:=jsonb_build_object('at',items->19->>'at','key',items->19->>'key');items:=items-20;end if;return jsonb_build_object('items',items,'nextCursor',cursor);end $$;
create or replace function pro_private_estimate_append_only() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$begin raise exception 'Immutable private estimate audit' using errcode='23514';end $$;
drop trigger if exists pro_private_estimate_action_immutable on pro_private_estimate_actions;create trigger pro_private_estimate_action_immutable before update on pro_private_estimate_actions for each row execute function pro_private_estimate_append_only();
drop trigger if exists pro_private_estimate_history_immutable on pro_private_estimate_history;create trigger pro_private_estimate_history_immutable before update on pro_private_estimate_history for each row execute function pro_private_estimate_append_only();
do $$declare t text;f record;begin foreach t in array array['pro_private_estimates','pro_private_estimate_items','pro_private_estimate_actions','pro_private_estimate_history']loop execute format('alter table %I enable row level security',t);execute format('revoke all on %I from public,anon,authenticated',t);execute format('grant all on %I to service_role',t);end loop;for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'pro_private_estimate_%' loop execute format('revoke all on function %s from public,anon,authenticated',f.signature);execute format('grant execute on function %s to service_role',f.signature);end loop;end $$;
commit;
notify pgrst, 'reload schema';

-- ===== private-team-access-local.sql =====
-- LOCAL Pro only. Allowlist10 owner entitlement substitutions; members remain free.
-- Verified invitation/email, work scope, roles, generations, receipts and audit unchanged.
begin;
create or replace function public.pro_team_context(p_actor uuid,p_grant uuid,p_write boolean default false) returns public.pro_team_grants
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare g public.pro_team_grants;
begin
 if not exists(select 1 from public.profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into g from public.pro_team_grants where id=p_grant;
 if not found or not coalesce(public.pro_private_work_tools_enabled(g.owner_id),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_actor<>g.owner_id and (g.member_user_id<>p_actor or not g.active or p_write and g.role<>'contributor') then raise exception 'Forbidden' using errcode='42501';end if;
 return g;
end $$;
create or replace function public.pro_team_owned_read(p_actor uuid,p_after text default null) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare items jsonb;cursor_id text;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_after is not null and (length(p_after) not between 1 and 160 or not exists(select 1 from public.pro_work where user_id=p_actor and id=p_after)) then raise exception 'Invalid team work cursor' using errcode='22023';end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',w.id,'service',w.service,'stage',w.stage,'cancelled',coalesce(w.cancelled,false),'start',w.start) order by w.id),'[]'::jsonb) into items from (
  select id,service,stage,cancelled,start from public.pro_work where user_id=p_actor and (p_after is null or id>p_after) order by id limit 21
 ) w;
 if jsonb_array_length(items)>20 then cursor_id:=items->19->>'id';items:=items-20;end if;return jsonb_build_object('items',items,'nextCursor',cursor_id);
end $$;
create or replace function public.pro_team_owner_read(p_actor uuid,p_work text,p_kind text default 'members',p_after uuid default null) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare items jsonb;cursor_id uuid;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) or not exists(select 1 from public.pro_work where user_id=p_actor and id=p_work) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_kind is null or p_kind not in('members','invites') then raise exception 'Invalid team view' using errcode='22023';end if;
 if p_kind='members' then
  if p_after is not null and not exists(select 1 from public.pro_team_grants where owner_id=p_actor and work_id=p_work and id=p_after) then raise exception 'Invalid member cursor' using errcode='22023';end if;
  select coalesce(jsonb_agg(public.pro_team_grant_json(g::public.pro_team_grants) order by g.id),'[]'::jsonb) into items from (select * from public.pro_team_grants where owner_id=p_actor and work_id=p_work and (p_after is null or id>p_after) order by id limit 21) g;
 else
  if p_after is not null and not exists(select 1 from public.pro_team_invites where owner_id=p_actor and work_id=p_work and id=p_after) then raise exception 'Invalid invitation cursor' using errcode='22023';end if;
  select coalesce(jsonb_agg(public.pro_team_invite_json(i::public.pro_team_invites) order by i.id),'[]'::jsonb) into items from (select * from public.pro_team_invites where owner_id=p_actor and work_id=p_work and (p_after is null or id>p_after) order by id limit 21) i;
 end if;
 if jsonb_array_length(items)>20 then cursor_id:=(items->19->>'id')::uuid;items:=items-20;end if;return jsonb_build_object('workId',p_work,'items',items,'nextCursor',cursor_id);
end $$;
create or replace function public.pro_team_shared_read(p_actor uuid,p_after uuid default null) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare items jsonb;cursor_id uuid;
begin
 if not exists(select 1 from public.profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_after is not null and not exists(select 1 from public.pro_team_grants where id=p_after and member_user_id=p_actor and active and public.pro_private_work_tools_enabled(owner_id)) then raise exception 'Invalid shared-work cursor' using errcode='22023';end if;
 select coalesce(jsonb_agg(public.pro_team_shared_grant_json(g::public.pro_team_grants,p_actor) order by g.id),'[]'::jsonb) into items from (select * from public.pro_team_grants where member_user_id=p_actor and active and public.pro_private_work_tools_enabled(owner_id) and (p_after is null or id>p_after) order by id limit 21) g;
 if jsonb_array_length(items)>20 then cursor_id:=(items->19->>'id')::uuid;items:=items-20;end if;return jsonb_build_object('items',items,'nextCursor',cursor_id,'canManage',coalesce(public.pro_private_work_tools_enabled(p_actor),false));
end $$;
create or replace function public.pro_team_mutate(p_actor uuid,p_input jsonb,p_verified_email text default null) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text;aid uuid;owner uuid;wid text;gid uuid;iid uuid;tid uuid;rev integer;keys text[];email text;code_hash text;wanted_role text;body_text text;
 i public.pro_team_invites;g public.pro_team_grants;t public.pro_work_tasks;r public.pro_team_actions;c public.pro_team_comments;
 before_json jsonb;after_json jsonb;full_before jsonb;answer jsonb;actor_name text;event_task uuid;event_title text;event_grant uuid;event_role text;has_grant boolean;
begin
 if not exists(select 1 from public.profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input) is distinct from 'object' then raise exception 'Invalid team operation' using errcode='22023';end if;
 act:=p_input->>'action';
 if act is null or act not in('invite','accept','cancel_invite','set_role','revoke','comment','complete','reopen') or jsonb_typeof(p_input->'actionId') is distinct from 'string' then raise exception 'Invalid team identity' using errcode='22023';end if;
 aid:=(p_input->>'actionId')::uuid;select array_agg(key order by key) into keys from jsonb_object_keys(p_input) key;
 if act='invite' then
  if keys<>array['action','actionId','codeHash','email','role','workId'] or jsonb_typeof(p_input->'email') is distinct from 'string' or jsonb_typeof(p_input->'role') is distinct from 'string' then raise exception 'Invalid invitation fields' using errcode='22023';end if;
  email:=p_input->>'email';wanted_role:=p_input->>'role';
  if email<>lower(btrim(email)) or length(email)>254 or email !~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' or wanted_role not in('viewer','contributor') then raise exception 'Invalid invitation' using errcode='22023';end if;
 elsif act='accept' then
  if keys<>array['action','actionId','codeHash'] then raise exception 'Invalid acceptance fields' using errcode='22023';end if;
 elsif act='cancel_invite' then
  if keys<>array['action','actionId','inviteId','revision','workId'] or jsonb_typeof(p_input->'inviteId') is distinct from 'string' then raise exception 'Invalid invitation cancellation' using errcode='22023';end if;iid:=(p_input->>'inviteId')::uuid;
 elsif act in('set_role','revoke') then
  if (act='set_role' and keys<>array['action','actionId','grantId','revision','role','workId']) or (act='revoke' and keys<>array['action','actionId','grantId','revision','workId']) or jsonb_typeof(p_input->'grantId') is distinct from 'string' then raise exception 'Invalid member change' using errcode='22023';end if;
  gid:=(p_input->>'grantId')::uuid;
  if act='set_role' then wanted_role:=p_input->>'role';if jsonb_typeof(p_input->'role') is distinct from 'string' or wanted_role not in('viewer','contributor') then raise exception 'Invalid role' using errcode='22023';end if;end if;
 elsif act='comment' then
  if keys<>array['action','actionId','grantId','text'] or jsonb_typeof(p_input->'grantId') is distinct from 'string' or jsonb_typeof(p_input->'text') is distinct from 'string' then raise exception 'Invalid team comment' using errcode='22023';end if;
  gid:=(p_input->>'grantId')::uuid;body_text:=btrim(p_input->>'text');if length(body_text) not between 1 and 1000 then raise exception 'Invalid comment' using errcode='22023';end if;
 else
  if keys<>array['action','actionId','grantId','revision','taskId'] or jsonb_typeof(p_input->'grantId') is distinct from 'string' or jsonb_typeof(p_input->'taskId') is distinct from 'string' then raise exception 'Invalid team task action' using errcode='22023';end if;
  gid:=(p_input->>'grantId')::uuid;tid:=(p_input->>'taskId')::uuid;
 end if;
 if act in('invite','accept') then
  if jsonb_typeof(p_input->'codeHash') is distinct from 'string' or not coalesce((p_input->>'codeHash')~'^[a-f0-9]{64}$',false) then raise exception 'Invalid code hash' using errcode='22023';end if;code_hash:=p_input->>'codeHash';
 end if;
 if act in('cancel_invite','set_role','revoke','complete','reopen') then
  if jsonb_typeof(p_input->'revision') is distinct from 'number' or not coalesce((p_input->>'revision')~'^[0-9]{1,10}$',false) or (p_input->>'revision')::numeric not between 1 and 2147483646 then raise exception 'Invalid revision' using errcode='22023';end if;rev:=(p_input->>'revision')::integer;
 end if;
 if act in('invite','cancel_invite','set_role','revoke') then
  if jsonb_typeof(p_input->'workId') is distinct from 'string' or length(p_input->>'workId') not between 1 and 160 then raise exception 'Invalid job identity' using errcode='22023';end if;owner:=p_actor;wid:=p_input->>'workId';
  if not coalesce(public.pro_private_work_tools_enabled(owner),false) or not exists(select 1 from public.pro_work where user_id=owner and id=wid) then raise exception 'Forbidden' using errcode='42501';end if;
 elsif act='accept' then
  select * into i from public.pro_team_invites where token_sha256=code_hash;
  if not found or p_verified_email is null or lower(btrim(p_verified_email)) is distinct from i.recipient_email or i.owner_id=p_actor or not coalesce(public.pro_private_work_tools_enabled(i.owner_id),false) then raise exception 'Code unavailable' using errcode='42501';end if;owner:=i.owner_id;wid:=i.work_id;
 else
  g:=public.pro_team_context(p_actor,gid,true);owner:=g.owner_id;wid:=g.work_id;
 end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-team-action:'||p_actor::text||':'||aid::text,0));
 -- Match the existing owner task writer: owner/work advisory, grant, task.
 -- Revocation and role changes take this identical lock before returning receipts.
 perform pg_advisory_xact_lock(hashtextextended('pro-work-tasks:'||owner::text||':'||wid,0));
 if act='accept' then
  select * into i from public.pro_team_invites where token_sha256=code_hash for update;
  if not found or i.owner_id<>owner or i.work_id<>wid or p_verified_email is null or lower(btrim(p_verified_email)) is distinct from i.recipient_email or not coalesce(public.pro_private_work_tools_enabled(owner),false) then raise exception 'Code unavailable' using errcode='42501';end if;
  select * into g from public.pro_team_grants where owner_id=owner and work_id=wid and member_user_id=p_actor for update;has_grant:=found;
  if i.status='accepted' then
   if i.accepted_by is distinct from p_actor or i.accept_action_id is distinct from aid or not has_grant or not g.active or g.id is distinct from i.grant_id or g.source_invite_id is distinct from i.id then raise exception 'Code unavailable' using errcode='42501';end if;
  elsif i.status<>'pending' or i.expires_at<=now() or has_grant and g.active then raise exception 'Code unavailable' using errcode='42501';end if;
 elsif act='cancel_invite' then
  select * into i from public.pro_team_invites where id=iid and owner_id=owner and work_id=wid for update;if not found then raise exception 'Forbidden' using errcode='42501';end if;
 elsif act in('set_role','revoke') then
  select * into g from public.pro_team_grants where id=gid and owner_id=owner and work_id=wid for update;if not found then raise exception 'Forbidden' using errcode='42501';end if;
 elsif act in('comment','complete','reopen') then
  select * into g from public.pro_team_grants where id=gid for update;if not found then raise exception 'Forbidden' using errcode='42501';end if;
  g:=public.pro_team_context(p_actor,gid,true);
  if g.owner_id<>owner or g.work_id<>wid then raise exception 'Forbidden' using errcode='42501';end if;
  if act in('complete','reopen') then
   select * into t from public.pro_work_tasks where owner_id=owner and work_id=wid and id=tid and not archived for update;if not found then raise exception 'Forbidden' using errcode='42501';end if;
  end if;
 end if;
 if not coalesce(public.pro_private_work_tools_enabled(owner),false) or not exists(select 1 from public.profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 -- Never return an old committed result to a revoked/downgraded collaborator.
 select * into r from public.pro_team_actions where actor_id=p_actor and action_id=aid;
 if found then
  if r.input is distinct from p_input then raise exception 'Action identity reused with different payload' using errcode='22023';end if;return r.result;
 end if;
 actor_name:=public.pro_team_name(p_actor);
 if act='invite' then
  insert into public.pro_team_invites(id,owner_id,work_id,recipient_email,role,token_sha256,expires_at) values(aid,owner,wid,email,wanted_role,code_hash,now()+interval '72 hours') returning * into i;
  after_json:=jsonb_build_object('role',i.role,'status',i.status,'revision',i.revision);event_role:=i.role;
  answer:=jsonb_build_object('action',act,'ownerId',owner,'workId',wid,'invite',public.pro_team_invite_json(i));
 elsif act='accept' then
  if i.status<>'pending' then raise exception 'Code unavailable' using errcode='42501';end if;
  if has_grant then
   before_json:=jsonb_build_object('role',g.role,'active',g.active,'revision',g.revision);
   if g.revision>=2147483647 then raise exception 'Member revision exhausted' using errcode='54000';end if;
   update public.pro_team_grants set role=i.role,active=true,revision=revision+1,source_invite_id=i.id,member_name=actor_name,updated_at=now() where id=g.id returning * into g;
  else
   insert into public.pro_team_grants(id,owner_id,work_id,member_user_id,member_name,role,source_invite_id) values(gen_random_uuid(),owner,wid,p_actor,actor_name,i.role,i.id) returning * into g;
  end if;
  update public.pro_team_invites set status='accepted',revision=revision+1,accepted_by=p_actor,grant_id=g.id,accept_action_id=aid where id=i.id returning * into i;
  after_json:=jsonb_build_object('role',g.role,'active',g.active,'revision',g.revision);event_grant:=g.id;event_role:=g.role;
  answer:=jsonb_build_object('action',act,'ownerId',owner,'workId',wid,'grant',public.pro_team_grant_json(g));
 elsif act='cancel_invite' then
  if rev<>i.revision or i.status='accepted' then raise exception 'Invitation changed' using errcode='40001';end if;
  if i.status<>'pending' then raise exception 'Invitation unavailable' using errcode='22023';end if;
  before_json:=jsonb_build_object('role',i.role,'status',i.status,'revision',i.revision);
  update public.pro_team_invites set status='revoked',revision=revision+1 where id=i.id returning * into i;
  after_json:=jsonb_build_object('role',i.role,'status',i.status,'revision',i.revision);event_role:=i.role;
  answer:=jsonb_build_object('action',act,'ownerId',owner,'workId',wid,'invite',public.pro_team_invite_json(i));
 elsif act in('set_role','revoke') then
  if rev<>g.revision or not g.active then raise exception 'Member changed' using errcode='40001';end if;
  before_json:=jsonb_build_object('role',g.role,'active',g.active,'revision',g.revision);
  update public.pro_team_grants set role=case when act='set_role' then wanted_role else role end,active=act<>'revoke',revision=revision+1,updated_at=now() where id=g.id returning * into g;
  after_json:=jsonb_build_object('role',g.role,'active',g.active,'revision',g.revision);event_grant:=g.id;event_role:=g.role;
  answer:=jsonb_build_object('action',act,'ownerId',owner,'workId',wid,'grant',public.pro_team_grant_json(g));
 elsif act='comment' then
  insert into public.pro_team_comments(id,owner_id,work_id,actor_id,actor_name,text) values(aid,owner,wid,p_actor,actor_name,body_text) returning * into c;
  after_json:=jsonb_build_object('commentId',c.id);event_grant:=g.id;event_role:=g.role;
  answer:=jsonb_build_object('action',act,'ownerId',owner,'workId',wid,'comment',public.pro_team_comment_json(c));
 else
  if rev<>t.revision then raise exception 'Task changed' using errcode='40001';end if;
  if act='complete' and t.status<>'open' or act='reopen' and t.status<>'done' then raise exception 'Invalid task transition' using errcode='22023';end if;
  full_before:=public.pro_work_task_json(t);before_json:=public.pro_team_task_json(t);
  update public.pro_work_tasks set status=case when act='complete' then 'done' else 'open' end,revision=revision+1,updated_at=now() where owner_id=owner and id=tid returning * into t;
  after_json:=public.pro_team_task_json(t);event_task:=t.id;event_title:=t.title;event_grant:=g.id;event_role:=g.role;
  -- owner_id below is storage scope, NOT the actor. Real actor is recorded in
  -- team_events/actions; never call the existing owner mutation as p_owner.
  insert into public.pro_work_task_history(owner_id,work_id,task_id,action_id,action,before_task,after_task) values(owner,wid,tid,aid,act,full_before,public.pro_work_task_json(t));
  answer:=jsonb_build_object('action',act,'ownerId',owner,'workId',wid,'task',after_json);
 end if;
 insert into public.pro_team_events(owner_id,work_id,actor_id,actor_name,action_id,action,task_id,title,grant_id,role,before_projected,after_projected)
 values(owner,wid,p_actor,actor_name,aid,act,event_task,event_title,event_grant,event_role,before_json,after_json);
 insert into public.pro_team_actions(actor_id,action_id,owner_id,work_id,input,result) values(p_actor,aid,owner,wid,p_input,answer);return answer;
end $$;
create or replace function public.pro_team_action_read(p_actor uuid,p_action uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare r public.pro_team_actions;i public.pro_team_invites;g public.pro_team_grants;t public.pro_work_tasks;c public.pro_team_comments;act text;
begin
 if not exists(select 1 from public.profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into r from public.pro_team_actions where actor_id=p_actor and action_id=p_action;if not found then return null;end if;act:=r.input->>'action';
 if act in('invite','cancel_invite','set_role','revoke') then
  if r.owner_id<>p_actor or not coalesce(public.pro_private_work_tools_enabled(p_actor),false) or not exists(select 1 from public.pro_work where user_id=p_actor and id=r.work_id) then raise exception 'Forbidden' using errcode='42501';end if;
  if act in('invite','cancel_invite') then
   select * into i from public.pro_team_invites where id=case when act='invite' then p_action else (r.input->>'inviteId')::uuid end and owner_id=p_actor and work_id=r.work_id;
   if not found then return null;end if;
   return jsonb_build_object('action',act,'ownerId',r.owner_id,'workId',r.work_id,'invite',public.pro_team_invite_json(i));
  end if;
  select * into g from public.pro_team_grants where id=(r.input->>'grantId')::uuid and owner_id=p_actor and work_id=r.work_id;if not found then return null;end if;
  return jsonb_build_object('action',act,'ownerId',r.owner_id,'workId',r.work_id,'grant',public.pro_team_grant_json(g));
 elsif act='accept' then
  select * into i from public.pro_team_invites where token_sha256=r.input->>'codeHash';
  if not found or i.status<>'accepted' or i.accepted_by is distinct from p_actor or i.accept_action_id is distinct from p_action then raise exception 'Forbidden' using errcode='42501';end if;
  g:=public.pro_team_context(p_actor,i.grant_id,false);
  if not g.active or g.source_invite_id<>i.id or g.owner_id<>r.owner_id or g.work_id<>r.work_id then raise exception 'Forbidden' using errcode='42501';end if;
  return jsonb_build_object('action',act,'ownerId',r.owner_id,'workId',r.work_id,'grant',public.pro_team_grant_json(g));
 else
  g:=public.pro_team_context(p_actor,(r.input->>'grantId')::uuid,true);
  if g.owner_id<>r.owner_id or g.work_id<>r.work_id then raise exception 'Forbidden' using errcode='42501';end if;
  if act='comment' then
   select * into c from public.pro_team_comments where id=p_action and owner_id=r.owner_id and work_id=r.work_id and actor_id=p_actor;if not found then return null;end if;
   return jsonb_build_object('action',act,'ownerId',r.owner_id,'workId',r.work_id,'comment',public.pro_team_comment_json(c));
  end if;
  select * into t from public.pro_work_tasks where owner_id=r.owner_id and work_id=r.work_id and id=(r.input->>'taskId')::uuid and not archived;
  if not found then raise exception 'Forbidden' using errcode='42501';end if;
  return jsonb_build_object('action',act,'ownerId',r.owner_id,'workId',r.work_id,'task',public.pro_team_task_json(t));
 end if;
end $$;
create or replace function public.pro_team_task_assign(p_actor uuid,p_input jsonb) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare aid uuid;wid text;tid uuid;gid uuid;rev integer;keys text[];t public.pro_work_tasks;g public.pro_team_grants;r public.pro_team_actions;before_json jsonb;full_before jsonb;answer jsonb;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input) is distinct from 'object' then raise exception 'Invalid assignment' using errcode='22023';end if;
 select array_agg(key order by key) into keys from jsonb_object_keys(p_input) key;
 if keys is distinct from array['action','actionId','assigneeGrantId','revision','taskId','workId'] or p_input->>'action' is distinct from 'assign' or jsonb_typeof(p_input->'actionId') is distinct from 'string' or jsonb_typeof(p_input->'taskId') is distinct from 'string' or jsonb_typeof(p_input->'workId') is distinct from 'string' or jsonb_typeof(p_input->'assigneeGrantId') not in('string','null') or jsonb_typeof(p_input->'revision') is distinct from 'number' or not coalesce((p_input->>'revision')~'^[0-9]{1,10}$',false) then raise exception 'Invalid assignment fields' using errcode='22023';end if;
 aid:=(p_input->>'actionId')::uuid;tid:=(p_input->>'taskId')::uuid;gid:=(p_input->>'assigneeGrantId')::uuid;wid:=p_input->>'workId';
 if length(wid) not between 1 and 160 or (p_input->>'revision')::numeric not between 1 and 2147483646 then raise exception 'Invalid assignment scope' using errcode='22023';end if;rev:=(p_input->>'revision')::integer;
 perform pg_advisory_xact_lock(hashtextextended('pro-team-action:'||p_actor::text||':'||aid::text,0));
 perform pg_advisory_xact_lock(hashtextextended('pro-work-tasks:'||p_actor::text||':'||wid,0));
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) or not exists(select 1 from public.pro_work where user_id=p_actor and id=wid) then raise exception 'Forbidden' using errcode='42501';end if;
 -- Shared receipt namespace also blocks reuse through the older team writer.
 select * into r from public.pro_team_actions where actor_id=p_actor and action_id=aid;
 if found then if r.input is distinct from p_input then raise exception 'Action identity reused' using errcode='22023';end if;return r.result;end if;
 if gid is not null then
  select * into g from public.pro_team_grants where id=gid and owner_id=p_actor and work_id=wid for update;
  if not found or not g.active or g.role<>'contributor' or not exists(select 1 from public.profiles where id=g.member_user_id and not coalesce(is_disabled,false)) then raise exception 'Member unavailable' using errcode='40001';end if;
 end if;
 select * into t from public.pro_work_tasks where owner_id=p_actor and work_id=wid and id=tid and not archived for update;
 if not found then raise exception 'Forbidden' using errcode='42501';end if;
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if gid is not null and (not g.active or g.role<>'contributor' or not exists(select 1 from public.profiles where id=g.member_user_id and not coalesce(is_disabled,false))) then raise exception 'Member unavailable' using errcode='40001';end if;
 if t.revision<>rev then raise exception 'Task changed' using errcode='40001';end if;
 before_json:=public.pro_team_task_json(t);full_before:=public.pro_work_task_json(t);
 if gid is null then delete from public.pro_team_task_assignments where owner_id=p_actor and task_id=tid;
 else insert into public.pro_team_task_assignments(owner_id,work_id,task_id,grant_id,source_invite_id,display_name) values(p_actor,wid,tid,g.id,g.source_invite_id,g.member_name)
 on conflict(owner_id,task_id) do update set grant_id=excluded.grant_id,source_invite_id=excluded.source_invite_id,display_name=excluded.display_name,updated_at=now();end if;
 update public.pro_work_tasks set revision=revision+1,updated_at=now() where owner_id=p_actor and id=tid returning * into t;
 insert into public.pro_work_task_history(owner_id,work_id,task_id,action_id,action,before_task,after_task) values(p_actor,wid,tid,aid,'update',full_before,public.pro_work_task_json(t));
 insert into public.pro_team_events(owner_id,work_id,actor_id,actor_name,action_id,action,task_id,title,grant_id,before_projected,after_projected)
 values(p_actor,wid,p_actor,public.pro_team_name(p_actor),aid,'assign',tid,t.title,gid,before_json,public.pro_team_task_json(t));
 answer:=jsonb_build_object('action','assign','ownerId',p_actor,'workId',wid,'task',public.pro_team_task_json(t));
 insert into public.pro_team_actions(actor_id,action_id,owner_id,work_id,input,result) values(p_actor,aid,p_actor,wid,p_input,answer);return answer;
end $$;
create or replace function public.pro_team_assignment_action_read(p_actor uuid,p_action uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare r public.pro_team_actions;t public.pro_work_tasks;
begin
 select * into r from public.pro_team_actions where actor_id=p_actor and action_id=p_action;
 if not found or r.input->>'action'<>'assign' then return public.pro_team_action_read(p_actor,p_action);end if;
 if r.owner_id<>p_actor or not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into t from public.pro_work_tasks where owner_id=p_actor and work_id=r.work_id and id=(r.input->>'taskId')::uuid and not archived;
 if not found then raise exception 'Forbidden' using errcode='42501';end if;
 return jsonb_build_object('action','assign','ownerId',p_actor,'workId',r.work_id,'task',public.pro_team_task_json(t));
end $$;
create or replace function public.pro_team_audit_read(p_actor uuid,p_work text,p_after uuid default null) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare items jsonb;cursor_id uuid;cursor_at timestamptz;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) or not exists(select 1 from public.pro_work where user_id=p_actor and id=p_work) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_after is not null then select at into cursor_at from public.pro_team_events where owner_id=p_actor and work_id=p_work and id=p_after;if not found then raise exception 'Invalid audit cursor' using errcode='22023';end if;end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',e.id,'actionId',e.action_id,'actorId',e.actor_id,'actorName',e.actor_name,'action',e.action,'at',e.at,'taskId',e.task_id,'title',e.title,'grantId',e.grant_id,'role',e.role,'assignmentBefore',e.before_projected->'assignment','assignmentAfter',e.after_projected->'assignment') order by e.at desc,e.id desc),'[]'::jsonb) into items from (
  select * from public.pro_team_events where owner_id=p_actor and work_id=p_work and (p_after is null or (at,id)<(cursor_at,p_after)) order by at desc,id desc limit 21
 ) e;
 if jsonb_array_length(items)>20 then cursor_id:=(items->19->>'id')::uuid;items:=items-20;end if;return jsonb_build_object('workId',p_work,'items',items,'nextCursor',cursor_id);
end $$;
create or replace function public.pro_team_task_notice_allowed(p_actor uuid,p_notice public.pro_team_task_notices) returns boolean language sql stable security invoker set search_path=public,pg_temp as $$
 select p_notice.recipient_id=p_actor and exists(select 1 from public.profiles p where p.id=p_actor and not coalesce(p.is_disabled,false)) and coalesce(public.pro_private_work_tools_enabled(p_notice.owner_id),false)
 and exists(select 1 from public.pro_work_tasks t where t.owner_id=p_notice.owner_id and t.work_id=p_notice.work_id and t.id=p_notice.task_id and not t.archived)
 and (p_actor=p_notice.owner_id or exists(select 1 from public.pro_team_grants g where g.id=p_notice.recipient_grant_id and g.owner_id=p_notice.owner_id and g.work_id=p_notice.work_id and g.member_user_id=p_actor and g.active and g.source_invite_id=p_notice.recipient_source_invite_id));
$$;
